(globalThis.TURBOPACK||(globalThis.TURBOPACK=[])).push(["object"==typeof document?document.currentScript:void 0,99879,(e,t,a)=>{t.exports=JSON.parse('{"meta":{"title":"SMSTS question bank","checked":"2026-10","source":"Imported from smsts-trainer (checked Oct 2026) plus new questions (prefixes N2-, N3-)","examFormat":"CITB Appendix G v03.04 (Feb 2026): 18 x 1-mark + 7 x 2-mark = 32 marks; official pass 26/32 (81%); 35 minutes; GE700 in the last 15 minutes."},"questions":[{"id":"L01","type":"mcq","marks":1,"part":"A","module":1,"topic":"Legal","question":"Which section of the Health and Safety at Work etc. Act 1974 places general duties on employers towards their own employees?","options":["Section 2","Section 3","Section 7","Section 8"],"answer":0,"citation":"HSWA s.2","rationale":"Employer must ensure, so far as is reasonably practicable, the health, safety and welfare of employees (plant/systems, substances, information/instruction/training/supervision, workplace, environment and welfare)."},{"id":"L02","type":"mcq","marks":1,"part":"A","module":1,"topic":"Legal","question":"An operative removes a guard rail to make it easier to pass materials up. Which HSWA section does this breach?","options":["Section 2","Section 6","Section 8","Section 37"],"answer":2,"citation":"HSWA s.8","rationale":"No person shall intentionally or recklessly interfere with or misuse anything provided in the interests of health, safety or welfare."},{"id":"L03","type":"mcq","marks":1,"part":"A","module":1,"topic":"Legal","question":"HSWA section 3 places duties on employers towards:","options":["Their own employees only","Persons not in their employment, such as the public and other contractors","Manufacturers and suppliers","Directors and senior managers"],"answer":1,"citation":"HSWA s.3","rationale":"Conduct the undertaking so that persons not in your employment (public, visitors, other trades) are not exposed to risks, SFAIRP."},{"id":"L04","type":"mcq","marks":1,"part":"A","module":1,"topic":"Legal","question":"An employer must have a WRITTEN health and safety policy when they employ:","options":["1 or more employees","5 or more employees","10 or more employees","20 or more employees"],"answer":1,"citation":"HSWA s.2(3)","rationale":"Written policy (statement of intent, organisation, arrangements) required with 5 or more employees. MHSWR reg 3 also requires significant risk-assessment findings to be recorded at 5+."},{"id":"L05","type":"mcq","marks":1,"part":"A","module":1,"topic":"Legal","question":"Under HSWA s.9, may an employer charge an employee for hearing protection required by law?","options":["Yes, at cost price","Yes, if the employee loses it","No, items required by law must be free","Only if the employee is self-employed"],"answer":2,"citation":"HSWA s.9","rationale":"No charge may be levied on employees for anything done or provided to meet a specific legal requirement, e.g. PPE."},{"id":"L06","type":"mcq","marks":1,"part":"A","module":1,"topic":"Legal","question":"Under the Corporate Manslaughter and Corporate Homicide Act 2007, which penalty CANNOT be imposed?","options":["An unlimited fine","A publicity order","A remedial order","Imprisonment of the organisation\'s directors under this Act"],"answer":3,"citation":"Corporate Manslaughter and Corporate Homicide Act 2007","rationale":"CMCHA 2007 applies to organisations only - Unlimited fine, remedial order, publicity order. Individuals can be prosecuted separately (gross negligence manslaughter, HSWA s.7/s.37)."},{"id":"C01","type":"mcq","marks":1,"part":"A","module":1,"topic":"CDM 2015","question":"Under CDM 2015 reg 6, a project must be notified to HSE (F10) when construction work is scheduled to:","options":["Last more than 30 working days with more than 20 workers simultaneously at any point, OR exceed 500 person days","Last more than 30 days OR involve more than 5 workers","Exceed 300 person days only","Involve more than one contractor"],"answer":0,"citation":"CDM 2015 reg 6(1)","rationale":">30 working days AND >20 workers simultaneously, OR >500 person days. Notice displayed in the site office."},{"id":"C02","type":"mcq","marks":1,"part":"A","module":1,"topic":"CDM 2015","question":"Who has the legal duty to notify HSE of a notifiable project?","options":["The principal contractor","The principal designer","The client","The site manager"],"answer":2,"citation":"CDM 2015 reg 6(2)","rationale":"The client must notify HSE in writing as soon as practicable before the construction phase begins (others may submit it on the client\'s behalf)."},{"id":"C03","type":"mcq","marks":1,"part":"A","module":1,"topic":"CDM 2015","question":"Under CDM 2015, a principal designer and principal contractor must be appointed when:","options":["The project is notifiable","There is (or will be) more than one contractor","The project lasts more than 30 days","The client is a domestic client"],"answer":1,"citation":"CDM 2015 reg 5","rationale":"Appointments are triggered by more than one contractor, NOT by notification."},{"id":"C04","type":"mcq","marks":1,"part":"A","module":1,"topic":"CDM 2015","question":"Who must draw up the construction phase plan on a project with more than one contractor?","options":["The client","The principal designer","The principal contractor","Each contractor separately"],"answer":2,"citation":"CDM 2015 reg 12(1)","rationale":"The PC draws up the CPP before the construction phase begins (on single-contractor jobs the contractor does it)."},{"id":"C05","type":"mcq","marks":1,"part":"A","module":1,"topic":"CDM 2015","question":"Who prepares the health and safety file?","options":["The principal designer","The principal contractor","The HSE","The building control officer"],"answer":0,"citation":"CDM 2015 reg 12(5)","rationale":"The PD prepares, reviews and updates the H&S file; it is handed to the client at the end of the project (the PC takes over if the PD\'s appointment ends first)."},{"id":"C06","type":"mcq","marks":1,"part":"A","module":1,"topic":"CDM 2015","question":"A homeowner has an extension built by two contractors and has made no written agreement with the designer. Who takes on the client duties?","options":["The homeowner","The principal contractor","The local authority","Nobody - domestic work is exempt"],"answer":1,"citation":"CDM 2015 reg 7","rationale":"Domestic client duties pass to the contractor (single contractor) or the PC (more than one contractor), unless agreed in writing with the PD."},{"id":"C07","type":"mcq","marks":1,"part":"A","module":1,"topic":"CDM 2015","question":"When must the construction phase plan be in place?","options":["Within 7 days of starting on site","Before the construction phase begins","Before handover to the client","Only when HSE requests it"],"answer":1,"citation":"CDM 2015 regs 4(5) and 12","rationale":"The client must ensure a CPP is drawn up before the construction phase begins."},{"id":"E01","type":"mcq","marks":1,"part":"A","module":1,"topic":"Enforcement","question":"An HSE inspector may serve a prohibition notice when they believe an activity:","options":["Breaches any regulation","Involves a risk of serious personal injury","Has caused a RIDDOR-reportable incident","Has no written risk assessment"],"answer":1,"citation":"HSWA s.22","rationale":"Prohibition notice where there is a risk of serious personal injury; a legal breach is not required. Work stops immediately (or when deferred)."},{"id":"E02","type":"mcq","marks":1,"part":"A","module":1,"topic":"Enforcement","question":"The minimum period an improvement notice must allow for compliance is:","options":["7 days","14 days","21 days","28 days"],"answer":2,"citation":"HSWA s.21","rationale":"Not less than 21 days (the same as the period for lodging an appeal). An appeal suspends an improvement notice."},{"id":"E03","type":"mcq","marks":1,"part":"A","module":1,"topic":"Enforcement","question":"What is the effect of appealing against a prohibition notice?","options":["The notice is suspended until the appeal is heard","The notice remains in force unless the tribunal directs otherwise","The notice is cancelled","HSE must re-inspect within 7 days"],"answer":1,"citation":"HSWA s.24","rationale":"An appeal does NOT suspend a prohibition notice (unlike an improvement notice)."},{"id":"E04","type":"mcq","marks":1,"part":"A","module":1,"topic":"Enforcement","question":"From 1 April 2026, the HSE Fee for Intervention (FFI) hourly rate is:","options":["£129","£166","£174","£188"],"answer":3,"citation":"Health and Safety and Nuclear (Fees) Regs 2022 (rate from 1 Apr 2026)","rationale":"FFI £188 per hour. It is triggered by a material breach (e.g. a notification of contravention)."},{"id":"E05","type":"mcq","marks":1,"part":"A","module":1,"topic":"Enforcement","question":"Fee for Intervention is charged when an inspector:","options":["Makes any visit to a site","Identifies a material breach that requires formal written action","Is called to a RIDDOR incident","Gives verbal advice"],"answer":1,"citation":"Health and Safety and Nuclear (Fees) Regs 2022","rationale":"FFI only applies where there is a material breach (NoC, notice or prosecution)."},{"id":"H01","type":"mcq","marks":1,"part":"A","module":4,"topic":"Working at height","safetyCritical":true,"question":"Under the Work at Height Regulations 2005, what must be considered FIRST?","options":["Provide fall-arrest harnesses","Avoid work at height where reasonably practicable","Install safety nets","Use a ladder for short-duration work"],"answer":1,"citation":"WAHR reg 6 hierarchy","rationale":"AVOID -> PREVENT (existing safe place, collective, personal) -> MITIGATE (collective, personal).","safetyNote":"Falls from height are the biggest killer in construction. Always start by asking whether the work can be done from the ground."},{"id":"H02","type":"mcq","marks":1,"part":"A","module":4,"topic":"Working at height","safetyCritical":true,"question":"A scaffold working platform (fall of 2 m or more) on a construction site must be inspected:","options":["Monthly, and after alterations","Before first use, at least every 7 days, and after any event (e.g. high winds) that could affect its stability","Every 14 days only","Only when the scaffold contractor visits"],"answer":1,"citation":"WAHR 2005 reg 12","rationale":"Inspect after installation before use, within the previous 7 days, and after exceptional circumstances. Report before the end of the working period, copy within 24 h; keep on site, then 3 months.","safetyNote":"Never allow use of an uninspected or red-tagged scaffold. Storms, impacts and removed ties cause collapses."},{"id":"H03","type":"mcq","marks":1,"part":"A","module":4,"topic":"Working at height","question":"The minimum height of the top (main) guard rail under WAHR Schedule 2 is:","options":["910 mm","950 mm","1000 mm","1100 mm"],"answer":1,"citation":"WAHR Sch 2","rationale":"Main guard rail at least 950 mm; unprotected gap no more than 470 mm; toe boards suitable (industry 150 mm)."},{"id":"H04","type":"mcq","marks":1,"part":"A","module":4,"topic":"Working at height","question":"The maximum unprotected gap between guard rails (or between a guard rail and toe board) is:","options":["350 mm","470 mm","500 mm","600 mm"],"answer":1,"citation":"WAHR Sch 2","rationale":"The unprotected gap must not exceed 470 mm."},{"id":"H05","type":"mcq","marks":1,"part":"A","module":4,"topic":"Working at height","question":"A leaning ladder should be set at what angle?","options":["60 degrees (1 in 2)","70 degrees (1 in 3)","75 degrees (1 in 4)","85 degrees (1 in 8)"],"answer":2,"citation":"HSE INDG455","rationale":"75 degrees, the 1 in 4 rule; extend 1 m above the landing; secure it; short-duration (under ~30 min), light work only."},{"id":"H06","type":"mcq","marks":1,"part":"A","module":4,"topic":"Working at height","safetyCritical":true,"question":"Which control for roof-edge work is HIGHEST in the WAHR hierarchy (where work at height cannot be avoided)?","options":["Fall-arrest harness and lanyard","Safety netting below","Edge protection with guard rails and toe boards","Supervision and training"],"answer":2,"citation":"WAHR regs 6-7","rationale":"Prevent falls with collective measures (guard rails) before personal ones; mitigation (nets, harnesses) comes after prevention.","safetyNote":"Collective protection before personal protection - a harness protects only the wearer, and only if it is clipped on with a rescue plan."},{"id":"H07","type":"mcq","marks":1,"part":"A","module":4,"topic":"Working at height","safetyCritical":true,"question":"Operatives are about to walk across an asbestos-cement roof to reach a gutter. What should you assume?","options":["It will carry their weight if they step on the bolt lines","It is fragile and must not be walked on without platforms/coverings and edge/fall protection","It is safe if it is dry","It is safe with a harness clipped to the ridge"],"answer":1,"citation":"WAHR reg 9 and HSG33","rationale":"Treat roof sheets and rooflights as fragile; avoid passing across them; otherwise use platforms, coverings, guard rails, netting and signs.","safetyNote":"Falls through fragile roofs and rooflights kill every year. Assume fragile until proven otherwise."},{"id":"X01","type":"mcq","marks":1,"part":"A","module":4,"topic":"Excavations","safetyCritical":true,"question":"An excavation that people work in must be inspected by a competent person:","options":["Once a week","At the start of every shift, after any event affecting its stability, and after any accidental fall of material","Only after heavy rain","Before it is backfilled"],"answer":1,"citation":"CDM 2015 reg 22(4)","rationale":"Start of each shift, after an event likely to affect strength/stability, after an accidental fall of rock/earth. Reg 24 - only one written report per 7 days for routine shift inspections; keep on site, then 3 months.","safetyNote":"A cubic metre of soil weighs 1.5-2 tonnes. Never let anyone into an unsupported or uninspected trench."},{"id":"X02","type":"mcq","marks":1,"part":"A","module":4,"topic":"Excavations","safetyCritical":true,"question":"A CAT scan has located a buried electricity cable. Before excavating with a machine near it you should:","options":["Dig with the machine but slowly","Hand dig trial holes to confirm its exact position, using insulated tools","Rely on the utility drawings only","Ask the operator to watch for the cable"],"answer":1,"citation":"HSE HSG47","rationale":"Plan (drawings), locate (CAT and Genny), safe digging (hand-dug trial holes; no mechanical excavation within about 0.5 m). Treat all services as live.","safetyNote":"Striking a live cable can cause fatal burns. Plans are only indicative - always confirm by hand digging."},{"id":"X03","type":"mcq","marks":1,"part":"A","module":4,"topic":"Excavations","safetyCritical":true,"question":"Plant must regularly pass beneath overhead power lines on site. The BEST first step is to:","options":["Brief the drivers to keep their booms low","Contact the distribution network operator to divert or make the line dead; if not possible, provide goal-post crossing points and barriers","Fit warning flags to the cables","Use a banksman only"],"answer":1,"citation":"HSE GS6","rationale":"Divert or make dead first; otherwise barriers, goal posts with height limits, bunting, exclusion zones. Contact with an overhead line is a RIDDOR dangerous occurrence.","safetyNote":"Electricity can arc across a gap - you don\'t need to touch the line to be killed."},{"id":"P01","type":"mcq","marks":1,"part":"A","module":3,"topic":"Lifting and work equipment","question":"Under LOLER 1998, how often must lifting accessories (e.g. chain slings, shackles) be thoroughly examined?","options":["Every 3 months","Every 6 months","Every 12 months","Every 14 months"],"answer":1,"citation":"LOLER reg 9","rationale":"Accessories and equipment for lifting people: at least every 6 months; other lifting equipment every 12 months; or per a written examination scheme."},{"id":"P02","type":"mcq","marks":1,"part":"A","module":3,"topic":"Lifting and work equipment","question":"A MEWP used on site must have a thorough examination at least every:","options":["3 months","6 months","12 months","24 months"],"answer":1,"citation":"LOLER reg 9(3)","rationale":"Equipment for lifting persons: every 6 months (or per an examination scheme)."},{"id":"P03","type":"mcq","marks":1,"part":"A","module":3,"topic":"Lifting and work equipment","question":"Who should plan a lifting operation under LOLER reg 8 / BS 7121?","options":["The crane driver","A competent person, e.g. the Appointed Person","The slinger","The client"],"answer":1,"citation":"LOLER reg 8","rationale":"Every lifting operation must be properly planned by a competent person, appropriately supervised and carried out safely. BS 7121: Appointed Person, crane supervisor, slinger/signaller."},{"id":"P04","type":"mcq","marks":1,"part":"A","module":3,"topic":"Lifting and work equipment","question":"Under PUWER reg 11, the first measure for protecting against dangerous parts of machinery is:","options":["Information and training","Push sticks and jigs","Fixed enclosing guards","Supervision"],"answer":2,"citation":"PUWER reg 11 hierarchy","rationale":"Fixed guards -> other guards/protection devices -> protection appliances (jigs, push sticks) -> information, instruction, training and supervision."},{"id":"R01","type":"mcq","marks":1,"part":"A","module":1,"topic":"RIDDOR","question":"A worker is off work for 10 days after an accident at work. Under RIDDOR 2013 it must be reported within:","options":["24 hours","7 days","10 days","15 days"],"answer":3,"citation":"RIDDOR reg 4(2)","rationale":"Over-7-day incapacitation must be reported within 15 days of the accident. Over-3-day injuries are recorded only."},{"id":"R02","type":"mcq","marks":1,"part":"A","module":1,"topic":"RIDDOR","question":"Which of these is a RIDDOR \'specified injury\'?","options":["A fractured finger","A fractured forearm","A sprained ankle","A cut needing 4 stitches"],"answer":1,"citation":"RIDDOR reg 4(1)","rationale":"Fractures other than to fingers, thumbs and toes are specified injuries; notify without delay and report within 10 days."},{"id":"R03","type":"mcq","marks":1,"part":"A","module":1,"topic":"RIDDOR","question":"Collapse of a scaffold is a reportable dangerous occurrence when the scaffold is more than:","options":["2 m high","3 m high","5 m high","10 m high"],"answer":2,"citation":"RIDDOR Sch 2","rationale":"Complete or partial collapse of a scaffold more than 5 m high (or erected near water/suspended) is a dangerous occurrence."},{"id":"R04","type":"mcq","marks":1,"part":"A","module":1,"topic":"RIDDOR","question":"How long must RIDDOR records be kept?","options":["1 year","3 years","5 years","40 years"],"answer":1,"citation":"RIDDOR reg 12","rationale":"Keep records of reportable incidents and over-3-day injuries for at least 3 years."},{"id":"R05","type":"mcq","marks":1,"part":"A","module":1,"topic":"RIDDOR","question":"A member of the public trips over site materials on the pavement and is taken by ambulance straight to hospital for treatment. Is this RIDDOR reportable?","options":["No, RIDDOR only covers workers","Yes - non-workers taken from the scene directly to hospital for treatment","Only if they are off work for 7 days","Only if they make a claim"],"answer":1,"citation":"RIDDOR reg 5","rationale":"Injuries to non-workers that result in them being taken directly from the scene to hospital for treatment are reportable."},{"id":"K01","type":"mcq","marks":1,"part":"A","module":1,"topic":"RAMS and permits","question":"In the ERIC PD hierarchy, which is the MOST effective control?","options":["Isolate","Control","PPE","Eliminate"],"answer":3,"citation":"ERIC PD","rationale":"Eliminate, Reduce/substitute, Isolate, Control, PPE, Discipline. Elimination is most effective; PPE is the last resort."},{"id":"K02","type":"mcq","marks":1,"part":"A","module":1,"topic":"RAMS and permits","question":"Which of these is an ENGINEERING control for dust when cutting blocks?","options":["FFP3 mask","Job rotation","On-tool extraction (LEV)","Warning signs"],"answer":2,"citation":"COSHH 2002 reg 7 (hierarchy of control)","rationale":"Engineering controls (LEV, water suppression, guarding) come before administrative controls (rotation, signs) and PPE (masks)."},{"id":"K03","type":"mcq","marks":1,"part":"A","module":1,"topic":"RAMS and permits","safetyCritical":true,"question":"After hot work (e.g. grinding or torch-on roofing) is completed, a fire watch should normally be kept for at least:","options":["10 minutes","30 minutes","60 minutes","No fire watch needed if an extinguisher is present"],"answer":2,"citation":"HSG168 / Joint Code of Practice","rationale":"Fire watch during the work and for at least 60 minutes afterwards (insurers often require a further check up to 2 hours later). Follow the permit times.","safetyNote":"Smouldering fires from hot work often break out after everyone has left. Never skip the fire watch."},{"id":"K04","type":"mcq","marks":1,"part":"A","module":4,"topic":"Confined spaces","safetyCritical":true,"question":"Under the Confined Spaces Regulations 1997, what is the FIRST consideration?","options":["Provide breathing apparatus","Avoid entry if the work can be done another way","Test the atmosphere","Appoint a top person"],"answer":1,"citation":"Confined Spaces Regs 1997 reg 4","rationale":"Avoid entry; if unavoidable, a safe system of work (permit); reg 5 - emergency arrangements in place before entry.","safetyNote":"Many confined-space deaths are would-be rescuers. Never enter to rescue without proper equipment and training."},{"id":"K05","type":"mcq","marks":1,"part":"A","module":1,"topic":"RAMS and permits","question":"Which statement about a method statement is TRUE?","options":["A generic company method statement is always acceptable","It should describe step by step how the task will be done safely on THIS site, and be briefed to the operatives","It replaces the need for a risk assessment","It only needs signing by the client"],"answer":1,"citation":"MHSWR 1999 reg 3; CDM 2015 reg 15","rationale":"Method statements must be site- and task-specific, based on the risk assessment, and briefed to (and signed by) the workforce. Reject generic or vague RAMS."},{"id":"K06","type":"mcq","marks":1,"part":"A","module":3,"topic":"Electrical","safetyCritical":true,"question":"Under the Electricity at Work Regulations 1989 reg 14, work on or near live conductors is permitted only when:","options":["The electrician is qualified","It is unreasonable for the system to be dead, reasonable to work live, and suitable precautions are taken","The voltage is below 400 V","A permit has been signed by the client"],"answer":1,"citation":"EAWR reg 14","rationale":"All three conditions must be met; dead working (isolate, lock off, prove dead) is the default.","safetyNote":"Isolate, lock off with a personal lock, and PROVE DEAD with an approved tester before work."},{"id":"K07","type":"mcq","marks":1,"part":"A","module":1,"topic":"RAMS and permits","question":"Which of the following is NOT one of HSE\'s five steps to risk assessment?","options":["Identify the hazards","Decide who might be harmed and how","Obtain the client\'s signature","Review the assessment and update if necessary"],"answer":2,"citation":"HSE INDG163","rationale":"Identify hazards; who and how; evaluate and decide precautions; record and implement; review and update."},{"id":"W01","type":"mcq","marks":1,"part":"A","module":2,"topic":"Welfare","question":"Under CDM 2015 Schedule 2, washing facilities must include:","options":["Cold running water only","Hot and cold (or warm) running water, soap and a means of drying","Hand sanitiser only","A shower for every worker"],"answer":1,"citation":"CDM 2015 Sch 2 para 2","rationale":"Clean hot and cold or warm water, soap or other cleaning agent, towels or other means of drying; showers where the work requires them."},{"id":"W02","type":"mcq","marks":1,"part":"A","module":2,"topic":"Welfare","question":"Who must ensure that welfare facilities are provided throughout the construction phase on a multi-contractor project?","options":["Each worker","The principal contractor","The principal designer","The local authority"],"answer":1,"citation":"CDM 2015 reg 13(4)(c)","rationale":"The PC ensures Schedule 2 facilities are provided throughout the construction phase (the client must ensure this happens)."},{"id":"W03","type":"mcq","marks":1,"part":"A","module":2,"topic":"Welfare","question":"Rest facilities on site must include:","options":["A television","Tables and seating with backs, and a means of boiling water and preparing meals","A smoking shelter","Lockers for tools"],"answer":1,"citation":"CDM 2015 Sch 2 para 5","rationale":"Adequate tables and seating with backs; facilities to prepare and eat meals, including the means for boiling water; appropriate temperature."},{"id":"D01","type":"mcq","marks":1,"part":"A","module":2,"topic":"Dust","question":"The workplace exposure limit (WEL) for respirable crystalline silica is:","options":["0.01 mg/m3 8-hr TWA","0.1 mg/m3 8-hr TWA","1 mg/m3 8-hr TWA","10 mg/m3 8-hr TWA"],"answer":1,"citation":"HSE EH40","rationale":"RCS WEL 0.1 mg/m3 (8-hr TWA). RCS is a carcinogen, so exposure must be reduced as low as reasonably practicable (COSHH reg 7)."},{"id":"D02","type":"mcq","marks":1,"part":"A","module":2,"topic":"Dust","safetyCritical":true,"question":"What is the correct way to clean up silica dust after chasing walls?","options":["Dry sweeping with a stiff brush","Blowing it away with compressed air","Using an M- or H-class vacuum or wet methods","Leaving it for the cleaners"],"answer":2,"citation":"HSE CIS36 / Dust Kills","rationale":"Use vacuums with M/H-class filtration or wet methods; never dry sweep or use compressed air.","safetyNote":"Dry sweeping puts fine silica back into the air you and others breathe - it causes irreversible silicosis."},{"id":"D03","type":"mcq","marks":1,"part":"A","module":2,"topic":"Dust","question":"Before an operative uses a tight-fitting FFP3 disposable mask, they must have:","options":["A face-fit test for that model, and be clean-shaven where it seals","A CSCS card","An audiometry test","Nothing - masks are one size fits all"],"answer":0,"citation":"COSHH ACoP / HSE INDG479","rationale":"Tight-fitting RPE must be face-fit tested; facial hair under the seal makes it ineffective."},{"id":"N01","type":"mcq","marks":1,"part":"A","module":2,"topic":"Noise","question":"Under the Control of Noise at Work Regulations 2005, the UPPER exposure action value is:","options":["80 dB(A)","85 dB(A)","87 dB(A)","90 dB(A)"],"answer":1,"citation":"CNWR 2005","rationale":"LEAV 80 dB(A)/135 dB(C); UEAV 85 dB(A)/137 dB(C); ELV 87 dB(A)/140 dB(C). At the UEAV: noise-reduction programme, hearing protection zones, protection worn, health surveillance."},{"id":"N02","type":"mcq","marks":1,"part":"A","module":2,"topic":"Noise","question":"Which noise level takes into account the protection given by hearing protection?","options":["Lower exposure action value","Upper exposure action value","Exposure limit value (87 dB(A))","None of them"],"answer":2,"citation":"CNWR 2005 reg 4","rationale":"Only the exposure limit value (87 dB(A) / 140 dB(C)) takes account of hearing protection; it must not be exceeded."},{"id":"N03","type":"mcq","marks":1,"part":"A","module":2,"topic":"Noise","question":"If you have to shout to be heard by someone 2 m away, the noise level is likely to be at least:","options":["70 dB(A)","75 dB(A)","80 dB(A)","85 dB(A)"],"answer":3,"citation":"HSE rule of thumb","rationale":"Shouting to be heard at 2 m indicates about 85 dB(A) (the upper action value)."},{"id":"V01","type":"mcq","marks":1,"part":"A","module":2,"topic":"Vibration","question":"The daily exposure ACTION value for hand-arm vibration is:","options":["0.5 m/s2 A(8)","1.15 m/s2 A(8)","2.5 m/s2 A(8)","5.0 m/s2 A(8)"],"answer":2,"citation":"CVWR 2005","rationale":"HAV EAV 2.5 m/s2 (100 points), ELV 5.0 m/s2 (400 points). WBV EAV 0.5, ELV 1.15."},{"id":"V02","type":"mcq","marks":1,"part":"A","module":2,"topic":"Vibration","question":"Using the HSE points system, the HAV exposure LIMIT value equals:","options":["100 points","200 points","300 points","400 points"],"answer":3,"citation":"HSE HAV calculator","rationale":"100 points = EAV (2.5 m/s2); 400 points = ELV (5.0 m/s2), which must not be exceeded."},{"id":"V03","type":"mcq","marks":1,"part":"A","module":2,"topic":"Vibration","question":"Which of these is LEAST reliable as a control for hand-arm vibration?","options":["Using a low-vibration tool","Limiting trigger time","So-called anti-vibration gloves","Changing the work method to avoid breaking"],"answer":2,"citation":"HSE L140","rationale":"Anti-vibration gloves are not a reliable control; gloves are for warmth and dryness. Eliminate, reduce the magnitude, and limit time first."},{"id":"M01","type":"mcq","marks":1,"part":"A","module":2,"topic":"Manual handling","question":"Under the Manual Handling Operations Regulations 1992, the FIRST step is to:","options":["Assess the load using TILE","Avoid hazardous manual handling so far as is reasonably practicable","Train workers in lifting techniques","Provide back belts"],"answer":1,"citation":"MHOR reg 4","rationale":"Avoid -> Assess (TILE) -> Reduce. Mechanise or deliver to point of use first."},{"id":"M02","type":"mcq","marks":1,"part":"A","module":2,"topic":"Manual handling","question":"In a manual handling assessment, TILE stands for:","options":["Time, Injury, Lift, Effort","Task, Individual, Load, Environment","Training, Inspection, Lifting, Equipment","Task, Instruction, Location, Equipment"],"answer":1,"citation":"MHOR Sch 1 / HSE L23","rationale":"Task, Individual capability, Load, Environment (plus Other factors, e.g. PPE)."},{"id":"A01","type":"mcq","marks":1,"part":"A","module":2,"topic":"Asbestos","safetyCritical":true,"question":"A labourer uncovers material they suspect is asbestos lagging. What should happen FIRST?","options":["Wet it down and bag it","Stop work, leave the area and prevent others entering","Take a sample to the site office","Carry on but wear a dust mask"],"answer":1,"citation":"CAR 2012 / HSE emergency procedure","rationale":"STOP, evacuate and isolate the area, inform the site manager, don\'t disturb it, arrange sampling by a competent analyst.","safetyNote":"Asbestos kills around 5,000 people a year in GB. Never disturb suspected asbestos - stop and isolate."},{"id":"A02","type":"mcq","marks":1,"part":"A","module":2,"topic":"Asbestos","safetyCritical":true,"question":"Before refurbishing a 1975 office block, which asbestos survey is required?","options":["Management survey","Refurbishment and demolition survey","Visual walk-round by the site manager","No survey if the building looks modern"],"answer":1,"citation":"CAR 2012 reg 5 and HSG264","rationale":"An intrusive R&D survey is required before refurbishment or demolition; any buildings before 2000 may contain asbestos.","safetyNote":"Never start refurbishment or demolition without an R&D survey covering the work area."},{"id":"A03","type":"mcq","marks":1,"part":"A","module":2,"topic":"Asbestos","question":"The asbestos control limit under CAR 2012 is:","options":["0.01 fibres/cm3 over 4 hours","0.1 fibres/cm3 over 4 hours","1.0 fibres/cm3 over 8 hours","0.6 fibres/cm3 over 8 hours"],"answer":1,"citation":"CAR 2012 reg 2/12","rationale":"Control limit 0.1 f/cm3 averaged over 4 hours (peak 0.6 f/cm3 over 10 minutes). It is not a \'safe\' level."},{"id":"A04","type":"mcq","marks":1,"part":"A","module":2,"topic":"Asbestos","question":"How often should asbestos awareness training be refreshed?","options":["Every year","Every 3 years","Every 5 years","Never - once is enough"],"answer":0,"citation":"CAR 2012 reg 10 / ACoP L143","rationale":"Refresher training at least every year (it may be shorter or e-learning)."},{"id":"A05","type":"mcq","marks":1,"part":"A","module":2,"topic":"Asbestos","question":"Licensed asbestos work must be notified to the enforcing authority at least:","options":["24 hours before","7 days before","14 days before","28 days before"],"answer":2,"citation":"CAR 2012 reg 9","rationale":"At least 14 days before the licensed work starts (NNLW must be notified before work starts)."},{"id":"F01","type":"mcq","marks":1,"part":"A","module":3,"topic":"Fire","safetyCritical":true,"question":"Which extinguisher is suitable for a fire in an electrical distribution board?","options":["Water (red label)","Foam (cream label)","CO2 (black label)","Wet chemical (yellow label)"],"answer":2,"citation":"BS EN 3","rationale":"CO2 (black) for electrical and flammable liquids; dry powder (blue) also works but obscures vision. Never water on electrical fires.","safetyNote":"Water conducts electricity - using it on a live fire can electrocute you."},{"id":"F02","type":"mcq","marks":1,"part":"A","module":3,"topic":"Fire","question":"LPG cylinders on site should be stored:","options":["In the site canteen to keep them warm","Outside, upright, in a secure, well-ventilated compound away from drains and ignition sources","In the basement","Lying flat in the van"],"answer":1,"citation":"HSG168 / DSEAR 2002","rationale":"LPG is heavier than air and collects in low points; store outside, upright, secure and ventilated."},{"id":"F03","type":"mcq","marks":1,"part":"A","module":3,"topic":"Fire","question":"Who enforces fire precautions on a construction site under CDM 2015 regs 29-32?","options":["The fire and rescue authority","HSE","The local planning authority","The Building Safety Regulator"],"answer":1,"citation":"CDM 2015 regs 29-32; Regulatory Reform (Fire Safety) Order 2005","rationale":"HSE enforces CDM fire provisions on construction sites; the fire and rescue authority enforces the Fire Safety Order in occupied premises."},{"id":"G01","type":"mcq","marks":1,"part":"A","module":3,"topic":"Electrical","question":"The recommended supply voltage for portable electric hand tools on construction sites is:","options":["230 V","110 V centre-tapped to earth","400 V three-phase","12 V DC only"],"answer":1,"citation":"HSE / BS 7375","rationale":"110 V CTE (55 V maximum to earth), yellow plugs; or battery tools. 230 V only where unavoidable, with a 30 mA RCD."},{"id":"G02","type":"mcq","marks":1,"part":"A","module":3,"topic":"Electrical","question":"HSE guidance suggests 110 V portable tools on site should have a combined inspection and test (PAT) every:","options":["Week","Month","3 months","12 months"],"answer":2,"citation":"HSE INDG236","rationale":"110 V: user checks weekly, formal visual monthly, combined test before first use on site then every 3 months; 230 V: daily, weekly, monthly."},{"id":"Y01","type":"mcq","marks":1,"part":"A","module":4,"topic":"Environment","question":"How long must a non-hazardous Waste Transfer Note be kept?","options":["6 months","1 year","2 years","3 years"],"answer":2,"citation":"EPA 1990 s.34 Duty of Care / Waste (E&W) Regs 2011","rationale":"WTNs kept for 2 years; hazardous waste consignment notes for 3 years."},{"id":"Y02","type":"mcq","marks":1,"part":"A","module":4,"topic":"Environment","question":"The top (most preferred) level of the waste hierarchy is:","options":["Recycling","Prevention","Energy recovery","Disposal to landfill"],"answer":1,"citation":"Waste (E&W) Regs 2011 reg 12","rationale":"Prevention -> preparing for reuse -> recycling -> other recovery -> disposal."},{"id":"Y03","type":"mcq","marks":1,"part":"A","module":4,"topic":"Environment","question":"Before handing waste to a carrier, the site\'s legal Duty of Care requires you to:","options":["Check that the carrier is registered with the Environment Agency (or NRW/SEPA)","Pay in cash","Take a photo of the skip","Nothing - the carrier is responsible"],"answer":0,"citation":"EPA 1990 s.34","rationale":"Transfer only to an authorised person (registered carrier), with a written description (WTN), and check where the waste is going (a permitted site)."},{"id":"Y04","type":"mcq","marks":1,"part":"A","module":4,"topic":"Environment","question":"A bunded fuel tank should have secondary containment of at least:","options":["50% of the tank capacity","100% of the tank capacity","110% of the tank capacity","200% of the tank capacity"],"answer":2,"citation":"Control of Pollution (Oil Storage) (England) Regs 2001","rationale":"At least 110% of the largest container."},{"id":"T01","type":"mcq","marks":1,"part":"A","module":3,"topic":"Vehicles/pedestrians","safetyCritical":true,"question":"What is the MOST effective way of protecting pedestrians from site vehicles?","options":["Hi-vis clothing","Reversing alarms","Physical segregation of pedestrian and vehicle routes with barriers and separate gates","A speed limit sign"],"answer":2,"citation":"CDM 2015 reg 27","rationale":"Traffic routes organised so pedestrians and vehicles move safely; segregation (isolation) beats PPE and warnings.","safetyNote":"Being struck by a moving vehicle is one of the top causes of construction deaths. Separate people and plant."},{"id":"T02","type":"mcq","marks":1,"part":"A","module":3,"topic":"Vehicles/pedestrians","question":"The best way to reduce reversing accidents on site is to:","options":["Fit louder alarms","Design a one-way system / turning areas to minimise the need to reverse","Tell drivers to be careful","Allow only experienced drivers"],"answer":1,"citation":"HSE HSG144 / CDM reg 27","rationale":"Eliminate or minimise reversing (one-way systems, turning circles); where unavoidable, use trained vehicle marshals and visibility aids."},{"id":"Z01","type":"mcq","marks":1,"part":"A","module":3,"topic":"Temporary works","question":"Under BS 5975, who would normally issue a \'permit to load\' for temporary works?","options":["The scaffolder","The Temporary Works Co-ordinator","The client","The crane driver"],"answer":1,"citation":"BS 5975:2019","rationale":"The TWC co-ordinates TW, keeps the register, ensures design checks and issues permits to load and to dismantle (or delegates to a TWS)."},{"id":"B01","type":"mcq","marks":1,"part":"A","module":1,"topic":"Building Safety Act","question":"For the design and construction regime in England, a \'higher-risk building\' is one that is:","options":["Over 11 m high with any use","At least 18 m high or at least 7 storeys with at least 2 residential units (or a hospital/care home)","Any building with a basement","Over 30 m high only"],"answer":1,"citation":"Building Safety Act 2022 / HRB Regulations 2023","rationale":"18 m+ or 7+ storeys, 2+ residential units; hospitals and care homes of that height during design and construction."},{"id":"B02","type":"mcq","marks":1,"part":"A","module":1,"topic":"Building Safety Act","question":"Under the Building Safety Act regime for higher-risk buildings, building work must NOT start until:","options":["Gateway 1 planning consent is granted","Gateway 2 building control approval is granted by the Building Safety Regulator","The F10 is submitted","The completion certificate is issued"],"answer":1,"citation":"Building Regulations etc. (Amendment) (England) Regs 2023 (Gateway 2)","rationale":"Gateway 2 is a \'hard stop\' - BSR building control approval is needed before work starts. Gateway 3 = completion certificate before occupation. The BSR has been a standalone body since 27 Jan 2026."},{"id":"B03","type":"mcq","marks":1,"part":"A","module":1,"topic":"Building Safety Act","question":"The Principal Contractor under the Building Regulations (BSA dutyholder regime) is mainly responsible for:","options":["Health and safety during construction under CDM","Planning, managing and monitoring building work so it complies with building regulations","Paying the BSR\'s fees","Writing the fire statement"],"answer":1,"citation":"Building Regulations etc. (Amendment) (England) Regs 2023","rationale":"BSA PC = building-regulations compliance; CDM PC = health and safety. Often the same firm, but different duties."},{"id":"S01","type":"mcq","marks":1,"part":"A","module":3,"topic":"Site setup and signs","question":"A blue circular safety sign indicates:","options":["Prohibition","Warning","Mandatory action","Safe condition"],"answer":2,"citation":"Safety Signs and Signals Regs 1996","rationale":"Blue circle mandatory; red circle with bar prohibition; yellow triangle warning; green safe condition; red square fire equipment."},{"id":"S02","type":"mcq","marks":1,"part":"A","module":3,"topic":"Site setup and signs","question":"Which document must be displayed in the site office on a notifiable project?","options":["The H&S file","The F10 notification particulars","The client\'s tender documents","Designers\' risk registers"],"answer":1,"citation":"CDM 2015 reg 6(3)(b)","rationale":"The notice must be clearly displayed in the construction site office where workers can read it."},{"id":"O01","type":"mcq","marks":1,"part":"A","module":2,"topic":"Mental health and wellbeing","question":"The HSE Management Standards for work-related stress cover six areas: demands, control, support, relationships, role and:","options":["Pay","Change","Overtime","Welfare"],"answer":1,"citation":"HSE Management Standards","rationale":"Demands, Control, Support, Relationships, Role, Change."},{"id":"O02","type":"mcq","marks":1,"part":"A","module":2,"topic":"COSHH and health","question":"Which item is NOT covered by COSHH 2002 because it has its own regulations?","options":["Cement","Silica dust","Asbestos","Solvent-based paint"],"answer":2,"citation":"COSHH 2002 reg 5","rationale":"COSHH does not cover asbestos (CAR 2012), lead (CLAW 2002) or radioactive substances."},{"id":"O03","type":"mcq","marks":1,"part":"A","module":2,"topic":"COSHH and health","question":"Under COSHH, how often must local exhaust ventilation (LEV) be thoroughly examined and tested?","options":["Every 6 months","Every 12 months","At least every 14 months","Every 5 years"],"answer":2,"citation":"COSHH reg 9","rationale":"LEV thoroughly examined and tested at least every 14 months (more often for some processes); records kept 5 years."},{"id":"Q01","type":"mcq","marks":1,"part":"A","module":1,"topic":"Exam and course","question":"What is the SMSTS exam pass mark?","options":["70% (23/32)","75% (24/32)","81% (26/32)","90% (29/32)"],"answer":2,"citation":"CITB Appendix G v03.04 (Feb 2026)","rationale":"81% = 26/32. Scores of 23-25 allow one re-sit within 30 days."},{"id":"Q02","type":"mcq","marks":1,"part":"A","module":1,"topic":"Exam and course","question":"Under the current CITB rules (Feb 2026), the 2-day SMSTS-R refresher exam:","options":["Is the same format as SMSTS: 25 questions, 32 marks, pass 26/32 (81%)","Has 35 marks with a pass mark of 28","Requires all 5 safety-critical questions to be correct","Is open-book for the whole exam"],"answer":0,"citation":"CITB Appendix H v02.05 (Feb 2026)","rationale":"18 x 1 + 7 x 2 = 32 marks, 81% pass, 35 minutes, GE700 in the last 15 minutes. The old \'28/35 + safety-critical\' format is out of date."},{"id":"L07","type":"mcq","marks":1,"part":"A","module":1,"topic":"Legal","question":"According to HSE\'s 2025/26 provisional statistics, what is the most common cause of fatal injury to workers in Great Britain?","options":["Being struck by a moving vehicle","Contact with electricity","Falls from height","Being trapped by something collapsing"],"answer":2,"citation":"HSE, 1 July 2026","rationale":"Falls from height caused 31 of 126 worker deaths (about a quarter). Construction had the most deaths of any industry (25)."},{"id":"H08","type":"mcq","marks":1,"part":"A","module":4,"topic":"Working at height","safetyCritical":true,"question":"A worker in a fall-arrest harness has fallen and is hanging, conscious, waiting for help. What is the main immediate danger?","options":["Hypothermia","Suspension intolerance - loss of consciousness from blood pooling in the legs","The lanyard snapping","Dehydration"],"answer":1,"citation":"WAHR 2005 reg 4","rationale":"WAHR reg 4 requires rescue planning before work starts. Rescue as quickly as possible with trained people and equipment - never rely on the fire service as the plan (HSE RR708).","safetyNote":"Suspension intolerance can kill. No harness work without a rescue plan, equipment and trained rescuers on site."},{"id":"H09","type":"mcq","marks":1,"part":"A","module":4,"topic":"Working at height","question":"How often should harnesses and lanyards used in construction have a detailed inspection by a competent person?","options":["Only when new","At least every 6 months, and every 3 months for arduous use","Every 12 months","Every 14 months"],"answer":1,"citation":"HSE INDG367 / BS 8437","rationale":"Pre-use check by the user every time; detailed inspection at least 6-monthly (3-monthly for arduous conditions such as construction); remove from use after arresting a fall."},{"id":"H10","type":"mcq","marks":1,"part":"A","module":4,"topic":"Working at height","safetyCritical":true,"question":"Using a 2 m lanyard with an energy absorber, roughly how much clear space is needed below the anchor to arrest a fall safely?","options":["About 2 m","About 3 m","About 6 m or more","Clearance doesn\'t matter with an energy absorber"],"answer":2,"citation":"WAHR 2005 reg 6; BS 8437","rationale":"Free fall + energy absorber extension (~1.75 m) + D-ring-to-feet (~1.5-2 m) + safety margin (~1 m) is typically 6 m or more. With less clearance, use restraint, a self-retracting lifeline or collective protection.","safetyNote":"Fall arrest used too close to the ground lets the worker hit the floor before the system stops them."},{"id":"H11","type":"mcq","marks":1,"part":"A","module":4,"topic":"Working at height","question":"An operative in a boom-type MEWP basket should normally wear:","options":["No harness - the basket has guard rails","A harness with a short work-restraint lanyard clipped to the basket\'s anchor point","A harness with a 2 m fall-arrest lanyard clipped to the boom","A safety belt only"],"answer":1,"citation":"IPAF / HSE guidance","rationale":"Work restraint stops the operator being catapulted out of a boom MEWP; it prevents the fall rather than arresting it."},{"id":"T03","type":"mcq","marks":1,"part":"A","module":3,"topic":"Vehicles/pedestrians","safetyCritical":true,"question":"Buckets falling from excavator quick hitches have killed workers. The best control is:","options":["A banksman standing next to the bucket","Fully automatic quick hitches, with the operator checking the bucket is locked every time it is changed, and nobody in the swing zone","Only using quick hitches on small excavators","Greasing the hitch daily"],"answer":1,"citation":"HSE / CPA quick-hitch guidance","rationale":"Semi-automatic hitches depend on a manual safety pin that gets missed; use fully automatic hitches, do a locking check (visual/crowd test) and keep people out of the danger zone.","safetyNote":"A falling bucket weighs hundreds of kilograms. Stay out of the excavator\'s swing and dig zone."},{"id":"D04","type":"mcq","marks":1,"part":"A","module":2,"topic":"Dust","safetyCritical":true,"question":"A welder is welding mild steel inside a workshop for 20 minutes. What does HSE expect?","options":["Nothing - mild steel fume is harmless","Good general ventilation is enough for short jobs","Engineering control (usually local exhaust ventilation) whatever the duration, plus suitable RPE if LEV does not adequately control the fume","A dust mask only"],"answer":2,"citation":"HSE enforcement expectation (2019)","rationale":"All welding fume, including mild steel, can cause lung cancer; indoor welding needs LEV regardless of duration; add RPE where LEV is not adequate; outdoor welding needs RPE.","safetyNote":"Welding fume is a carcinogen. There is no \'safe\' short exposure."},{"id":"D05","type":"mcq","marks":1,"part":"A","module":2,"topic":"Dust","question":"Mild-steel welding fume is classed as:","options":["A nuisance dust only","A human carcinogen that can cause lung cancer","Safe below 10 mg/m3","An asphyxiant only"],"answer":1,"citation":"IARC Group 1 carcinogen","rationale":"HSE strengthened its enforcement expectation in 2019."},{"id":"A06","type":"mcq","marks":1,"part":"A","module":2,"topic":"Asbestos","question":"The EU cut its asbestos limit to 0.01 f/cm3 in December 2025. What is the GB control limit now?","options":["0.01 f/cm3 over 4 hours","0.1 f/cm3 over 4 hours - HSE decided not to lower it","0.6 f/cm3 over 8 hours","There is no longer a limit"],"answer":1,"citation":"HSE policy position (Dec 2025)","rationale":"The GB control limit stays 0.1 f/cm3 (4-hour average); exposure must still be reduced as low as reasonably practicable."},{"id":"Y05","type":"mcq","marks":1,"part":"A","module":4,"topic":"Environment","question":"Under Simpler Recycling (England), a workplace with 10+ employees must separate which waste streams (e.g. from the site office and canteen)?","options":["General waste only","Dry recyclables, food waste and residual waste","Hazardous waste only","Paper only"],"answer":1,"citation":"Environmental Protection Act 1990 s45AZB (Simpler Recycling)","rationale":"In force from 31 March 2025 for workplaces with 10 or more FTE employees (smaller ones from 31 March 2027): dry recyclables (plastic, metal, glass, paper/card), food waste and residual waste."},{"id":"Y06","type":"mcq","marks":1,"part":"A","module":4,"topic":"Environment","question":"From 1 October 2026, who in England must record waste movements in the government\'s digital waste tracking service?","options":["Every householder","Permitted and licensed waste receiving sites (wider phases expected later)","Only the Environment Agency","Nobody - it was cancelled"],"answer":1,"citation":"Digital Waste Tracking (England) Regulations 2026","rationale":"Receiving sites first from 1 Oct 2026; carriers, brokers, dealers and exempt sites expected in later phases. Keep using WTNs/consignment notes as normal."},{"id":"WH1","type":"written","marks":2,"part":"B","module":4,"topic":"Working at height","focusArea":"Working at height","safetyCritical":true,"question":"You are carrying out the weekly inspection of a tube-and-fitting scaffold. List TWO things you would check.","rubric":[{"label":"Guard rails / toe boards / brick guards in place","keywords":["guard rail","guardrail","handrail","toe board","toeboard","brick guard","edge protection"]},{"label":"Ties present and secure","keywords":["tie","ties","anchor"]},{"label":"Boards / platform complete, secure, not damaged","keywords":["board","platform","decking","boarded"]},{"label":"Base plates / sole boards / foundations sound","keywords":["base plate","baseplate","sole board","soleboard","foundation","ground"]},{"label":"Bracing / standards / ledgers / fittings intact","keywords":["brace","bracing","standard","ledger","transom","fitting","coupler","clip"]},{"label":"Safe access (ladder secured, 1 m above landing)","keywords":["ladder","access","stair"]},{"label":"Not overloaded / load class respected","keywords":["overload","load class","loading","materials stacked"]},{"label":"Scaffold tag / handover certificate / report","keywords":["tag","scafftag","handover","certificate"]}],"modelAnswer":"Any two of: guard rails (950 mm), intermediate rails and toe boards in place; ties present and not removed; boards complete, secure and undamaged; base plates and sole boards on firm ground; bracing, standards, ledgers and fittings intact; safe access ladder secured and 1 m above the landing; not overloaded beyond its load class; tag updated. Record on a WAHR Sch 7 report within the shift (copy within 24 h).","citation":"WAHR 2005 reg 12 and Sch 7; NASC TG20. Inspect before first use, at least every 7 days, and after adverse weather or alterations.","rationale":"Any two of: guard rails (950 mm), intermediate rails and toe boards in place; ties present and not removed; boards complete, secure and undamaged; base plates and sole boards on firm ground; bracing, standards, ledgers and fittings intact; safe access ladder secured and 1 m above the landing; not overloaded beyond its load class; tag updated. Record on a WAHR Sch 7 report within the shift (copy within 24 h).","safetyNote":"An unchecked scaffold can collapse or have missing edge protection - falls from height are the biggest construction killer."},{"id":"WH2","type":"written","marks":2,"part":"B","module":4,"topic":"Working at height","focusArea":"Working at height","safetyCritical":true,"question":"A gutter-repair gang plans to work from a leaning ladder for a full day along a 30 m elevation. Give TWO reasons why this is unacceptable OR TWO safer alternatives.","rubric":[{"label":"Ladders only for short-duration (under ~30 min), light, low-risk work","keywords":["short duration","short-duration","30 min","thirty min","too long","long duration","full day","short term","short period"]},{"label":"Ladders give no edge protection / fall prevention; overreaching","keywords":["no edge protection","no protection","overreach","fall","no guard","unstable","three points","3 points","hierarchy","collective"]},{"label":"Alternative: scaffold / mobile tower / MEWP / edge protection","keywords":["scaffold","tower","mewp","cherry picker","scissor","boom","podium","edge protection","access platform"]},{"label":"Alternative: avoid work at height / long-reach tools","keywords":["avoid","from the ground","ground level","long reach","pole"]}],"modelAnswer":"Ladders are only for low-risk, short-duration work (HSE: under about 30 minutes in one position) and give no collective edge protection, so a full day breaches WAHR regs 6-7 (collective before personal). Use a MEWP or mobile tower, or a scaffold with guard rails.","citation":"WAHR 2005 regs 6-7 and Sch 6; HSE INDG455 Safe use of ladders and stepladders.","rationale":"Ladders are only for low-risk, short-duration work (HSE: under about 30 minutes in one position) and give no collective edge protection, so a full day breaches WAHR regs 6-7 (collective before personal). Use a MEWP or mobile tower, or a scaffold with guard rails.","safetyNote":"Ladder falls cause many deaths and life-changing injuries. Plan for collective protection first."},{"id":"VP1","type":"written","marks":2,"part":"B","module":3,"topic":"Vehicles/pedestrians","focusArea":"Vehicles/pedestrians","safetyCritical":true,"question":"Give TWO measures you would include in a site traffic management plan to protect pedestrians from vehicles.","rubric":[{"label":"Segregated pedestrian routes / barriers","keywords":["segregat","barrier","separate walkway","separate route","pedestrian route","walkway","fence"]},{"label":"Separate pedestrian and vehicle gates","keywords":["separate gate","pedestrian gate","separate entrance","gate"]},{"label":"One-way system / minimise reversing / turning areas","keywords":["one way","one-way","reversing","turning","drive through"]},{"label":"Trained vehicle marshal / banksman","keywords":["banksman","banksmen","marshal","signaller","traffic marshal"]},{"label":"Speed limits, signage, lighting","keywords":["speed","sign","lighting","lit"]},{"label":"Visibility aids (cameras, mirrors, sensors) / hi-vis","keywords":["camera","cctv","mirror","sensor","proximity","visibility","hi vis","high vis"]},{"label":"Designated loading/unloading areas and crossing points","keywords":["crossing","loading","unloading","delivery area","delivery"]}],"modelAnswer":"Any two of: physically segregated pedestrian routes with barriers; separate pedestrian and vehicle gates; a one-way system and turning areas to minimise reversing; trained vehicle marshals where reversing is unavoidable; speed limits, signage and lighting; designated crossing points and delivery areas; visibility aids on plant.","citation":"CDM 2015 reg 27 (traffic routes) and reg 28 (vehicles); HSE HSG144 Safe use of vehicles on construction sites.","rationale":"Any two of: physically segregated pedestrian routes with barriers; separate pedestrian and vehicle gates; a one-way system and turning areas to minimise reversing; trained vehicle marshals where reversing is unavoidable; speed limits, signage and lighting; designated crossing points and delivery areas; visibility aids on plant.","safetyNote":"Being struck by a moving vehicle is a leading cause of death on site."},{"id":"VP2","type":"multi","marks":2,"part":"B","module":3,"topic":"Vehicles/pedestrians","focusArea":"Vehicles/pedestrians","question":"Which TWO of the following are the most effective ways to reduce the risk from reversing dumpers?","options":["Design a one-way system with turning areas so reversing is not needed","Make all pedestrians wear hi-vis","Use a trained vehicle marshal where reversing cannot be avoided, in a pedestrian-free zone","Tell drivers to sound the horn","Increase the speed limit so vehicles clear the area faster"],"answers":[0,2],"citation":"HSE HSG144","rationale":"Eliminate reversing first (one-way systems), then control it (trained marshals, exclusion zones, visibility aids). Hi-vis and horns are low-level controls."},{"id":"WH3","type":"written","marks":2,"part":"B","module":4,"topic":"Working at height","focusArea":"Working at height","safetyCritical":true,"question":"List TWO pre-use checks an operative should make on a full-body harness and energy-absorbing lanyard.","rubric":[{"label":"Webbing - cuts, fraying, burns, chemical/UV damage","keywords":["webbing","strap","cut","fray","burn","chemical","uv","fade"]},{"label":"Stitching intact","keywords":["stitch","sewing","seam"]},{"label":"Buckles / D-rings / metal parts - distortion, corrosion, cracks","keywords":["buckle","d ring","dring","metal","corros","rust","crack","distort"]},{"label":"Karabiner/hook gate closes and locks","keywords":["karabiner","carabiner","hook","gate","connector","lock"]},{"label":"Energy absorber intact, not deployed","keywords":["energy absorber","absorber","shock","deployed","pack"]},{"label":"Label legible, in date, inspection tag/record current","keywords":["label","tag","date","inspection record","inspected","serial"]}],"modelAnswer":"Any two of: webbing free of cuts, fraying, burns, chemical or UV damage; stitching intact; buckles, D-rings and metal parts not distorted, cracked or corroded; karabiner/hook gates close and lock; energy-absorber pack intact and not deployed; label legible and the 6-monthly detailed inspection in date. Remove from use if in doubt or if it has arrested a fall.","citation":"WAHR 2005 reg 12 and Sch 5; HSE INDG367. Detailed inspection every 6 months (3 months for arduous use).","rationale":"Any two of: webbing free of cuts, fraying, burns, chemical or UV damage; stitching intact; buckles, D-rings and metal parts not distorted, cracked or corroded; karabiner/hook gates close and lock; energy-absorber pack intact and not deployed; label legible and the 6-monthly detailed inspection in date. Remove from use if in doubt or if it has arrested a fall.","safetyNote":"A damaged harness or lanyard can fail exactly when it is needed."},{"id":"DU3","type":"written","marks":2,"part":"B","module":2,"topic":"Dust","focusArea":"Dust","safetyCritical":true,"question":"Give TWO controls for a fabricator welding steel brackets inside a building under construction.","rubric":[{"label":"Local exhaust ventilation / on-torch extraction","keywords":["lev","extract","local exhaust","on torch","fume hood","hood"]},{"label":"RPE (e.g. powered welding helmet/PAPR, face-fit tested) where LEV not adequate","keywords":["rpe","papr","powered","respirat","air fed","airfed","mask","ffp3","face fit"]},{"label":"Eliminate/reduce: pre-fabricate off site, bolted connections, cold methods","keywords":["off site","offsite","prefab","bolt","cold","eliminat","avoid welding"]},{"label":"Ventilation / keep others away / hot-work permit","keywords":["ventilat","keep others","exclusion","segregat","permit","screen"]},{"label":"Health surveillance / training / maintain LEV (14-monthly test)","keywords":["health surveillance","lung function","training","maintain","14 month","thorough examination"]}],"modelAnswer":"Any two of: eliminate or reduce welding on site (pre-fabricate, bolted connections); local exhaust ventilation/on-torch extraction - required for indoor welding whatever the duration; suitable RPE (e.g. powered welding helmet) where LEV doesn\'t adequately control fume; screens and exclusion of others under a hot-work permit; LEV maintained and thoroughly examined every 14 months; health surveillance and training.","citation":"COSHH 2002 reg 7; HSE welding fume enforcement expectation (2019) - all welding fume, including mild steel, is a carcinogen.","rationale":"Any two of: eliminate or reduce welding on site (pre-fabricate, bolted connections); local exhaust ventilation/on-torch extraction - required for indoor welding whatever the duration; suitable RPE (e.g. powered welding helmet) where LEV doesn\'t adequately control fume; screens and exclusion of others under a hot-work permit; LEV maintained and thoroughly examined every 14 months; health surveillance and training.","safetyNote":"Welding fume causes lung cancer. General ventilation alone is not enough indoors."},{"id":"MH1","type":"written","marks":2,"part":"B","module":2,"topic":"Manual handling","focusArea":"Manual handling","question":"Operatives are manually laying 70 kg concrete kerbs. Give TWO ways of reducing the manual handling risk.","rubric":[{"label":"Mechanical lifting aid (vacuum lifter, kerb lifter, excavator attachment)","keywords":["vacuum","lifter","mechanical","machine","excavator","attachment","lifting aid","handling aid","hoist","crane","grab","clamp","trolley"]},{"label":"Use lighter/smaller kerbs or a different product (e.g. lightweight or slip-form)","keywords":["lighter","lightweight","smaller","shorter kerb","half kerb","slip form","slipform","reduce the weight","reduce weight","plastic kerb"]},{"label":"Deliver close to the point of use / reduce carry distance","keywords":["point of use","close to","near","carry distance","distance","deliver"]},{"label":"Team handling / training / rest and rotation","keywords":["team","two person","two man","2 man","training","rotation","rotate","break"]}],"modelAnswer":"Avoid manual lifting by using a mechanical aid (vacuum kerb lifter, excavator-mounted lifting attachment). Reduce the load with lighter or shorter kerb units, or a different method such as slip-form kerbing. Deliver kerbs close to the point of use. Team handling and training are supplementary only.","citation":"MHOR 1992 reg 4: Avoid -> Assess (TILE) -> Reduce. 70 kg far exceeds the HSE guideline filter (25 kg men / 16 kg women at waist height close to the body).","rationale":"Avoid manual lifting by using a mechanical aid (vacuum kerb lifter, excavator-mounted lifting attachment). Reduce the load with lighter or shorter kerb units, or a different method such as slip-form kerbing. Deliver kerbs close to the point of use. Team handling and training are supplementary only."},{"id":"MH2","type":"written","marks":2,"part":"B","module":2,"topic":"Manual handling","focusArea":"Manual handling","question":"Name TWO of the factors considered in a manual handling risk assessment (TILE).","rubric":[{"label":"Task","keywords":["task"]},{"label":"Individual","keywords":["individual","person","capability"]},{"label":"Load","keywords":["load","weight"]},{"label":"Environment","keywords":["environment","floor","space","weather","lighting"]}],"modelAnswer":"Any two of: Task (twisting, stooping, carrying distance, frequency); Individual (capability, health, training, pregnancy, age); Load (weight, size, shape, grip, stability); Environment (space, floor conditions, slopes, weather, lighting).","citation":"MHOR 1992 Sch 1; HSE L23 and the MAC/RAPP tools.","rationale":"Any two of: Task (twisting, stooping, carrying distance, frequency); Individual (capability, health, training, pregnancy, age); Load (weight, size, shape, grip, stability); Environment (space, floor conditions, slopes, weather, lighting)."},{"id":"AS1","type":"written","marks":2,"part":"B","module":2,"topic":"Asbestos","focusArea":"Asbestos","safetyCritical":true,"question":"During strip-out, a joiner drills into a ceiling board that the asbestos register did not mention, and you suspect it is AIB. Give TWO immediate actions you would take.","rubric":[{"label":"Stop work immediately","keywords":["stop"]},{"label":"Evacuate / isolate / restrict access to the area, signs","keywords":["evacuat","isolat","seal","restrict","cordon","close","keep out","exclude","barrier","sign","leave the area","prevent access","lock"]},{"label":"Inform site manager / PC / client","keywords":["inform","report","tell","notify","manager","client"]},{"label":"Do not disturb / clean up; prevent spread; decontaminate exposed people","keywords":["not disturb","don\'t disturb","do not touch","don\'t touch","not sweep","spread","decontam","clothing","contaminat"]},{"label":"Arrange sampling/analysis by a competent (UKAS) analyst / licensed contractor","keywords":["sample","analys","test","ukas","survey","licensed","specialist"]},{"label":"Record exposure / consider RIDDOR","keywords":["record","riddor","exposure"]}],"modelAnswer":"STOP work immediately; evacuate and isolate the area (close doors, signs, prevent entry); inform the site manager/PC and client; do not disturb or sweep up the debris and prevent its spread (contain contaminated clothing); arrange sampling by a UKAS-accredited analyst; record who may have been exposed and consider a RIDDOR dangerous occurrence.","citation":"CAR 2012 regs 5, 11, 15-16; HSE asbestos emergency procedures; HSG264.","rationale":"STOP work immediately; evacuate and isolate the area (close doors, signs, prevent entry); inform the site manager/PC and client; do not disturb or sweep up the debris and prevent its spread (contain contaminated clothing); arrange sampling by a UKAS-accredited analyst; record who may have been exposed and consider a RIDDOR dangerous occurrence.","safetyNote":"Asbestos-related disease kills thousands every year and symptoms take 15-60 years to appear. Stop and isolate - never \'just finish the job\'."},{"id":"AS2","type":"written","marks":2,"part":"B","module":2,"topic":"Asbestos","focusArea":"Asbestos","question":"Name TWO diseases caused by exposure to asbestos.","rubric":[{"label":"Mesothelioma","keywords":["mesothelioma","meso"]},{"label":"Asbestos-related lung cancer","keywords":["lung cancer","cancer"]},{"label":"Asbestosis","keywords":["asbestosis"]},{"label":"Diffuse pleural thickening","keywords":["pleural","thickening","plaques"]}],"modelAnswer":"Any two of: mesothelioma; asbestos-related lung cancer; asbestosis; diffuse pleural thickening.","citation":"HSE - asbestos causes around 5,000 deaths a year in GB; latency 15-60 years.","rationale":"Any two of: mesothelioma; asbestos-related lung cancer; asbestosis; diffuse pleural thickening."},{"id":"DU1","type":"written","marks":2,"part":"B","module":2,"topic":"Dust","focusArea":"Dust","safetyCritical":true,"question":"A groundworker is cutting concrete kerbs with a petrol cut-off saw. Give TWO control measures to protect them from silica dust.","rubric":[{"label":"Water suppression on the saw","keywords":["water","wet","suppression","damp"]},{"label":"On-tool extraction / LEV with M- or H-class vacuum","keywords":["extract","lev","vacuum","hoover","h class","m class"]},{"label":"RPE: FFP3 (or equivalent) face-fit tested","keywords":["ffp3","rpe","respirat","face fit","mask","powered hood","face mask"]},{"label":"Eliminate/reduce cutting: order to size, block splitter, alternative method","keywords":["order","pre cut","precut","splitter","avoid cutting","design","alternative method","different method","eliminate"]},{"label":"Limit exposure time / keep others away / health surveillance","keywords":["limit time","rotation","exclusion","keep others","away","health surveillance","spirometry"]}],"modelAnswer":"Eliminate or reduce cutting (order to size, use a block splitter); use water suppression with a correct, constant flow on the saw (or on-tool extraction to an M/H-class vacuum); PLUS face-fit-tested FFP3 (APF 20) RPE as a secondary control; keep others away and limit exposure time; health surveillance (lung function).","citation":"COSHH 2002 reg 7; HSE CIS54/INDG463 \'Dust Kills\'. RCS WEL 0.1 mg/m3 (8-hr TWA).","rationale":"Eliminate or reduce cutting (order to size, use a block splitter); use water suppression with a correct, constant flow on the saw (or on-tool extraction to an M/H-class vacuum); PLUS face-fit-tested FFP3 (APF 20) RPE as a secondary control; keep others away and limit exposure time; health surveillance (lung function).","safetyNote":"RCS causes silicosis, COPD and lung cancer. A mask on its own is NOT an adequate control for cutting."},{"id":"DU2","type":"written","marks":2,"part":"B","module":2,"topic":"Dust","focusArea":"Dust","question":"Name TWO health effects of breathing in respirable crystalline silica (RCS).","rubric":[{"label":"Silicosis","keywords":["silicosis"]},{"label":"COPD / bronchitis / emphysema","keywords":["copd","chronic obstructive","bronchitis","emphysema"]},{"label":"Lung cancer","keywords":["cancer"]},{"label":"Kidney disease / other","keywords":["kidney","renal","tuberculosis","tb"]}],"modelAnswer":"Any two of: silicosis; chronic obstructive pulmonary disease (COPD); lung cancer; kidney disease (also increased risk of TB).","citation":"HSE construction dust guidance - RCS is a carcinogen; damage is irreversible.","rationale":"Any two of: silicosis; chronic obstructive pulmonary disease (COPD); lung cancer; kidney disease (also increased risk of TB)."},{"id":"NO1","type":"written","marks":2,"part":"B","module":2,"topic":"Noise","focusArea":"Noise","question":"Noise assessments show breaker operators are exposed above the UPPER exposure action value (85 dB(A)). Give TWO things the employer must do.","rubric":[{"label":"Programme of technical/organisational measures to reduce noise (quieter equipment/method, screens, time)","keywords":["reduce","quieter","programme","program","screen","barrier","enclos","silencer","maintain","different method","alternative","limit time","rotat"]},{"label":"Designate and sign hearing protection zones","keywords":["zone","sign"]},{"label":"Ensure hearing protection is provided AND worn","keywords":["hearing protection","ear defender","ear muff","earmuff","ear plug","earplug","worn","ppe"]},{"label":"Health surveillance (audiometry)","keywords":["health surveillance","audiometr","hearing test"]},{"label":"Information, instruction and training","keywords":["training","information","instruction","toolbox"]}],"modelAnswer":"Any two of: implement a programme of technical/organisational measures to reduce exposure (quieter methods or tools, maintenance, screens, limiting time); designate and sign hearing protection zones; provide hearing protection and ensure it is worn; provide health surveillance (audiometry); give information and training.","citation":"Control of Noise at Work Regs 2005 regs 6-7, 9-10 (L108). ELV 87 dB(A) must not be exceeded (taking account of hearing protection).","rationale":"Any two of: implement a programme of technical/organisational measures to reduce exposure (quieter methods or tools, maintenance, screens, limiting time); designate and sign hearing protection zones; provide hearing protection and ensure it is worn; provide health surveillance (audiometry); give information and training."},{"id":"NO2","type":"multi","marks":2,"part":"B","module":2,"topic":"Noise","focusArea":"Noise","question":"Which TWO of these are the noise action values under the Control of Noise at Work Regulations 2005?","options":["75 dB(A)","80 dB(A)","85 dB(A)","90 dB(A)","95 dB(A)"],"answers":[1,2],"citation":"CNWR 2005","rationale":"Lower EAV 80 dB(A) and upper EAV 85 dB(A); the exposure LIMIT value is 87 dB(A)."},{"id":"VI1","type":"written","marks":2,"part":"B","module":2,"topic":"Vibration","focusArea":"Vibration","question":"Name TWO symptoms of hand-arm vibration syndrome (HAVS).","rubric":[{"label":"Tingling / pins and needles","keywords":["tingl","pins and needles"]},{"label":"Numbness / loss of feeling","keywords":["numb","loss of feeling","loss of sensation"]},{"label":"Fingers going white (blanching) / vibration white finger","keywords":["white","blanch","pale","colour","color"]},{"label":"Loss of grip strength / dexterity","keywords":["grip","dexterity","strength","clumsy","fine work"]},{"label":"Pain / throbbing in hands, wrists, joints","keywords":["pain","ache","throb","joint"]}],"modelAnswer":"Any two of: tingling (pins and needles); numbness; fingers turning white (blanching) then red and painful (vibration white finger), especially in cold or wet; loss of grip strength and dexterity; pain in the hands, wrists and joints.","citation":"Control of Vibration at Work Regs 2005 (L140). HAVS and carpal tunnel are RIDDOR-reportable when diagnosed in writing.","rationale":"Any two of: tingling (pins and needles); numbness; fingers turning white (blanching) then red and painful (vibration white finger), especially in cold or wet; loss of grip strength and dexterity; pain in the hands, wrists and joints."},{"id":"VI2","type":"written","marks":2,"part":"B","module":2,"topic":"Vibration","focusArea":"Vibration","question":"Give TWO ways to reduce an operative\'s exposure to hand-arm vibration when breaking out concrete.","rubric":[{"label":"Alternative method / mechanise (e.g. remote demolition robot, excavator breaker, bursting, crushing)","keywords":["alternative","different method","robot","remote","excavator","machine mounted","mechanis","bursting","crusher","eliminate","avoid"]},{"label":"Low-vibration tools / maintenance","keywords":["low vibration","low-vibration","lower vibration","anti vibration tool","maintain","maintenance","sharp"]},{"label":"Limit trigger time / job rotation / monitor exposure (points)","keywords":["time","rotat","points","breaks","trigger"]},{"label":"Health surveillance / training / keep hands warm","keywords":["health surveillance","training","warm","gloves"]}],"modelAnswer":"Any two of: use an alternative method (remote-controlled demolition machine, excavator-mounted breaker, hydraulic bursting/crushing); select low-vibration tools and maintain them; limit trigger time with job rotation, using the HSE points system; health surveillance, training and keeping hands warm and dry.","citation":"CVWR 2005 reg 6 - eliminate or reduce to as low as reasonably practicable. EAV 2.5 m/s2 (100 points); ELV 5.0 m/s2 (400 points).","rationale":"Any two of: use an alternative method (remote-controlled demolition machine, excavator-mounted breaker, hydraulic bursting/crushing); select low-vibration tools and maintain them; limit trigger time with job rotation, using the HSE points system; health surveillance, training and keeping hands warm and dry."},{"id":"CD1","type":"written","marks":2,"part":"B","module":1,"topic":"CDM 2015","question":"List TWO duties of the principal contractor under CDM 2015.","rubric":[{"label":"Prepare / update the construction phase plan","keywords":["construction phase plan","cpp","phase plan"]},{"label":"Plan, manage, monitor and co-ordinate the construction phase / contractors","keywords":["co ordinat","coordinat","manage","monitor","plan"]},{"label":"Site induction","keywords":["induction"]},{"label":"Welfare facilities","keywords":["welfare","toilet","washing"]},{"label":"Prevent unauthorised access / site security","keywords":["unauthorised","unauthorized","access","secur","hoarding","fence"]},{"label":"Consult and engage with workers","keywords":["consult","engage","engagement"]},{"label":"Liaise with PD / provide info for the H&S file","keywords":["liaise","principal designer","health and safety file","h&s file","file"]}],"modelAnswer":"Any two of: plan, manage, monitor and co-ordinate the construction phase; draw up the construction phase plan before the construction phase begins; ensure suitable site inductions; prevent unauthorised access; provide Schedule 2 welfare; consult and engage with workers; liaise with the PD and provide information for the H&S file.","citation":"CDM 2015 regs 12-14.","rationale":"Any two of: plan, manage, monitor and co-ordinate the construction phase; draw up the construction phase plan before the construction phase begins; ensure suitable site inductions; prevent unauthorised access; provide Schedule 2 welfare; consult and engage with workers; liaise with the PD and provide information for the H&S file."},{"id":"EX1","type":"written","marks":2,"part":"B","module":4,"topic":"Excavations","safetyCritical":true,"question":"State TWO occasions when an excavation must be inspected by a competent person.","rubric":[{"label":"Start of every shift","keywords":["shift","daily","each day","every day","start of"]},{"label":"After an event likely to affect strength/stability (e.g. heavy rain, vibration, vehicle)","keywords":["event","rain","weather","flood","vibration","stability","strength","storm"]},{"label":"After an accidental fall of rock, earth or other material","keywords":["fall of","collapse","material","rock","earth","soil","fall"]}],"modelAnswer":"At the start of every shift in which work is to be done; after any event likely to have affected its strength or stability; after any accidental fall of rock, earth or other material. (Routine shift inspections need only one written report per 7 days; reports go to the person in control within 24 h and are kept for 3 months after the work.)","citation":"CDM 2015 regs 22(4) and 24 (verified legislation.gov.uk Oct 2026).","rationale":"At the start of every shift in which work is to be done; after any event likely to have affected its strength or stability; after any accidental fall of rock, earth or other material. (Routine shift inspections need only one written report per 7 days; reports go to the person in control within 24 h and are kept for 3 months after the work.)","safetyNote":"Trench collapses kill. No entry until the excavation has been inspected and found safe."},{"id":"RI1","type":"written","marks":2,"part":"B","module":1,"topic":"RIDDOR","question":"Give TWO examples of \'specified injuries\' that are reportable under RIDDOR 2013.","rubric":[{"label":"Fracture (other than fingers, thumbs, toes)","keywords":["fracture","broken","break"]},{"label":"Amputation","keywords":["amputat"]},{"label":"Loss / reduction of sight","keywords":["sight","eye","blind"]},{"label":"Crush injury to head or torso","keywords":["crush"]},{"label":"Serious burns (>10% body or vital organs)","keywords":["burn"]},{"label":"Scalping","keywords":["scalp"]},{"label":"Loss of consciousness (head injury / asphyxia)","keywords":["unconscious","consciousness","asphyx"]},{"label":"Enclosed space injury: hypothermia, heat illness, resuscitation, >24 h hospital","keywords":["hypotherm","heat","resuscitat","24 hour","24 hours","enclosed"]}],"modelAnswer":"Any two of: fractures other than to fingers, thumbs and toes; amputations; injury likely to cause permanent loss or reduction of sight; crush injuries to the head or torso damaging the brain or internal organs; serious burns (over 10% of the body or damaging eyes/respiratory system/vital organs); scalpings needing hospital treatment; loss of consciousness from head injury or asphyxia; enclosed-space injuries causing hypothermia or heat illness, or needing resuscitation or more than 24 h in hospital.","citation":"RIDDOR 2013 reg 4(1). Notify without delay; report within 10 days.","rationale":"Any two of: fractures other than to fingers, thumbs and toes; amputations; injury likely to cause permanent loss or reduction of sight; crush injuries to the head or torso damaging the brain or internal organs; serious burns (over 10% of the body or damaging eyes/respiratory system/vital organs); scalpings needing hospital treatment; loss of consciousness from head injury or asphyxia; enclosed-space injuries causing hypothermia or heat illness, or needing resuscitation or more than 24 h in hospital."},{"id":"HW1","type":"written","marks":2,"part":"B","module":1,"topic":"RAMS and permits","safetyCritical":true,"question":"List TWO precautions or conditions you would expect to see on a hot-work permit.","rubric":[{"label":"Remove or protect combustibles (e.g. within 10 m), fire blankets","keywords":["combustible","flammable","remove","blanket","screen","clear the area","10 m","10m"]},{"label":"Fire extinguisher at the work point","keywords":["extinguisher","fire fighting","firefighting"]},{"label":"Fire watch during and at least 60 minutes after","keywords":["fire watch","firewatch","60 min","one hour","1 hour","hour after","after completion","monitor"]},{"label":"Time-limited / valid for one shift / authorised issuer","keywords":["time","shift","expire","authoris","authoriz","valid"]},{"label":"Gas cylinders secured, flashback arrestors, check for flammable atmosphere","keywords":["cylinder","flashback","arrestor","gas test","atmosphere","lpg","acetylene"]},{"label":"Competent operative / consider avoiding hot work","keywords":["competent","trained","avoid","cold cut"]}],"modelAnswer":"Any two of: remove combustible materials from the area (or protect them with fire blankets/screens); fire extinguisher at the point of work; fire watch during the work and for at least 60 minutes afterwards; permit time-limited to one shift and issued by an authorised person; gas cylinders secured with flashback arrestors, and the area checked for flammable atmospheres; competent operative.","citation":"HSE HSG168 Fire safety in construction; HSG250 permit-to-work; Joint Code of Practice.","rationale":"Any two of: remove combustible materials from the area (or protect them with fire blankets/screens); fire extinguisher at the point of work; fire watch during the work and for at least 60 minutes afterwards; permit time-limited to one shift and issued by an authorised person; gas cylinders secured with flashback arrestors, and the area checked for flammable atmospheres; competent operative.","safetyNote":"Hot work is a leading cause of serious site fires."},{"id":"CS1","type":"written","marks":2,"part":"B","module":4,"topic":"Confined spaces","safetyCritical":true,"question":"Entry into a sewer chamber cannot be avoided. Give TWO precautions required before anyone enters.","rubric":[{"label":"Atmosphere tested (O2, flammable, toxic) and monitored","keywords":["test","gas","monitor","oxygen","atmospher","h2s"]},{"label":"Emergency rescue arrangements and equipment in place (tripod, winch, harness, BA)","keywords":["rescue","emergency","tripod","winch","harness","escape set","breathing apparatus"]},{"label":"Permit to work / safe system of work","keywords":["permit","safe system"]},{"label":"Trained, competent entrants","keywords":["trained","competent","training"]},{"label":"Top person / attendant / communications","keywords":["top man","top person","attendant","standby","communicat","radio"]},{"label":"Isolation of inflows/services, ventilation","keywords":["isolat","ventilat","lock off","blank"]}],"modelAnswer":"Any two of: a permit-to-work/safe system of work; test the atmosphere (oxygen ~20.9%, flammable, toxic e.g. H2S) before entry and monitor continuously; isolate inflows and services and ventilate; trained, competent entrants with a top person and communications; emergency rescue arrangements and equipment (tripod, winch, harness, escape sets, trained rescuers) in place BEFORE entry.","citation":"Confined Spaces Regulations 1997 regs 4-5; ACoP L101.","rationale":"Any two of: a permit-to-work/safe system of work; test the atmosphere (oxygen ~20.9%, flammable, toxic e.g. H2S) before entry and monitor continuously; isolate inflows and services and ventilate; trained, competent entrants with a top person and communications; emergency rescue arrangements and equipment (tripod, winch, harness, escape sets, trained rescuers) in place BEFORE entry.","safetyNote":"Oxygen-deficient or toxic air can kill within minutes, and rescuers often die too."},{"id":"WF1","type":"written","marks":2,"part":"B","module":2,"topic":"Welfare","question":"Name TWO of the welfare facilities required by CDM 2015 Schedule 2.","rubric":[{"label":"Sanitary conveniences (toilets)","keywords":["toilet","sanitary","wc","lavator"]},{"label":"Washing facilities (hot and cold/warm water, soap, drying)","keywords":["wash","sink","basin","soap","shower"]},{"label":"Drinking water","keywords":["drinking","drinkable","potable"]},{"label":"Changing rooms and lockers","keywords":["changing","locker","drying room"]},{"label":"Rest facilities (tables, seats, boiling water, meals)","keywords":["rest","canteen","mess","table","seat","kettle","boil","meal"]}],"modelAnswer":"Any two of: sanitary conveniences; washing facilities (hot and cold or warm water, soap, means of drying); drinking water; changing rooms and lockers; rest facilities (tables, seating with backs, means of boiling water and preparing meals).","citation":"CDM 2015 Schedule 2 - provided by the PC from the start and throughout the construction phase.","rationale":"Any two of: sanitary conveniences; washing facilities (hot and cold or warm water, soap, means of drying); drinking water; changing rooms and lockers; rest facilities (tables, seating with backs, means of boiling water and preparing meals)."},{"id":"N2-L01","type":"mcq","marks":1,"part":"A","module":1,"topic":"Legal","question":"Which section of the Health and Safety at Work etc. Act 1974 requires employees to take reasonable care of themselves and others affected by what they do or fail to do?","options":["Section 2","Section 3","Section 7","Section 37"],"answer":2,"citation":"HSWA 1974 s.7","rationale":"Section 7 duties on employees: take reasonable care for their own health and safety and that of others affected by their acts or omissions, and co-operate with the employer. Section 37 covers directors and managers."},{"id":"N2-L02","type":"mcq","marks":1,"part":"A","module":1,"topic":"Legal","question":"Under the Management of Health and Safety at Work Regulations 1999 (Schedule 1), the FIRST general principle of prevention is:","options":["Provide personal protective equipment","Avoid risks","Give appropriate instructions to employees","Adapt work to the individual"],"answer":1,"citation":"MHSWR 1999 Sch 1 (reg 4)","rationale":"The principles of prevention start with avoiding risks, then evaluating risks that cannot be avoided and combating them at source. Collective measures come before individual ones; PPE is the last resort."},{"id":"N2-C01","type":"mcq","marks":1,"part":"A","module":1,"topic":"CDM 2015","question":"Under CDM 2015, who must plan, manage, monitor and co-ordinate health and safety during the construction phase of a project with more than one contractor?","options":["The client","The principal designer","The principal contractor","The HSE inspector"],"answer":2,"citation":"CDM 2015 reg 13","rationale":"Reg 13(1): the principal contractor must plan, manage and monitor the construction phase and co-ordinate matters relating to health and safety, so that work is carried out without risks to health or safety so far as is reasonably practicable."},{"id":"N2-C02","type":"mcq","marks":1,"part":"A","module":1,"topic":"CDM 2015","question":"Under CDM 2015, which duty holder must make suitable arrangements for managing a project, including allowing sufficient time and resources?","options":["The client","The principal contractor","The site manager","The designer"],"answer":0,"citation":"CDM 2015 reg 4","rationale":"Reg 4(1)-(2): the client must make suitable arrangements for managing the project, including the allocation of sufficient time and other resources, and maintain and review them throughout."},{"id":"N2-C03","type":"mcq","marks":1,"part":"A","module":1,"topic":"CDM 2015","question":"When must the client send the F10 notification for a notifiable project to HSE?","options":["Within 10 days after work starts","As soon as practicable before the construction phase begins","Only once the health and safety file is complete","At the end of the project"],"answer":1,"citation":"CDM 2015 reg 6(2)","rationale":"The client must give notice in writing (form F10) as soon as is practicable before the construction phase begins. The notice must be displayed in the site office (reg 6(3))."},{"id":"N2-M01","type":"mcq","marks":1,"part":"A","module":1,"topic":"Leadership","question":"HSE\'s approach to managing health and safety (HSG65) is based on which cycle?","options":["Plan, Do, Check, Act","Identify, Assess, Control, Review","Avoid, Prevent, Mitigate","Eliminate, Reduce, Isolate, Control"],"answer":0,"citation":"HSE HSG65 Managing for health and safety","rationale":"HSG65 uses Plan, Do, Check, Act: plan the arrangements, do (deliver them), check performance (monitor and investigate) and act on lessons learned."},{"id":"N2-M02","type":"mcq","marks":1,"part":"A","module":1,"topic":"Leadership","question":"Which action by a site manager is MOST likely to build a positive safety culture?","options":["Staying in the site office and reviewing paperwork","Regularly walking the site, talking with operatives and acting on concerns they raise","Only discussing safety after an accident","Leaving safety to the health and safety adviser"],"answer":1,"citation":"HSE INDG417 Leading health and safety at work","rationale":"Visible, engaged leadership - managers seen on site, listening to the workforce and acting on what they hear - is a core principle of leading health and safety. Safety is a line-management responsibility, not just the adviser\'s."},{"id":"N2-H01","type":"mcq","marks":1,"part":"A","module":2,"topic":"COSHH and health","question":"Operatives will hot-cut old painted steelwork that may contain lead paint. Which regulations specifically apply to the lead exposure?","options":["COSHH 2002","Control of Lead at Work Regulations 2002","Control of Asbestos Regulations 2012","PUWER 1998"],"answer":1,"citation":"Control of Lead at Work Regulations 2002 (CLAW)","rationale":"Lead has its own regulations, so COSHH does not apply to it. CLAW requires a risk assessment, control of exposure, and medical surveillance (including blood-lead tests) where exposure is significant."},{"id":"N2-H02","type":"mcq","marks":1,"part":"A","module":2,"topic":"COSHH and health","question":"Under COSHH 2002, what must the employer do BEFORE work with a hazardous substance starts?","options":["Issue respirators to everyone","Carry out a suitable and sufficient COSHH risk assessment","Notify the HSE","Arrange a medical for every worker"],"answer":1,"citation":"COSHH 2002 reg 6","rationale":"Reg 6: an employer must not carry out work liable to expose employees to a hazardous substance unless a suitable and sufficient assessment of the risk has been made and the necessary control measures put in place."},{"id":"N2-R01","type":"mcq","marks":1,"part":"A","module":1,"topic":"RIDDOR","question":"A scaffold collapses (a reportable dangerous occurrence) but no one is hurt. What does RIDDOR 2013 require?","options":["Record it in the accident book only","Notify without delay, and send a report within 10 days","Report within 15 days","Report within 3 months"],"answer":1,"citation":"RIDDOR 2013 regs 4, 7 and Sch 2","rationale":"Deaths, specified injuries and dangerous occurrences must be notified by the quickest practicable means without delay, with a report received within 10 days. Over-7-day injuries: report within 15 days."},{"id":"N2-R02","type":"mcq","marks":1,"part":"A","module":1,"topic":"RIDDOR","question":"An operative is off work for 4 days after an injury at work. What does RIDDOR 2013 require?","options":["Report within 10 days","Report within 15 days","Record it (e.g. in the accident book); it is not reportable","Notify HSE by phone immediately"],"answer":2,"citation":"RIDDOR 2013 reg 12","rationale":"Over-3-day incapacitation must be recorded but is not reportable. Only over-7-day incapacitation is reported (within 15 days of the accident)."},{"id":"N2-F01","type":"mcq","marks":1,"part":"A","module":3,"topic":"Fire","question":"Under the Regulatory Reform (Fire Safety) Order 2005, who must carry out a fire risk assessment of the premises?","options":["The fire and rescue service","The \'responsible person\' (e.g. the employer or person in control of the premises)","The insurer","The local authority building control officer"],"answer":1,"citation":"Regulatory Reform (Fire Safety) Order 2005 arts 3 and 9","rationale":"The responsible person - the employer, or the person in control of the premises - must make a suitable and sufficient fire risk assessment and put general fire precautions in place."},{"id":"N2-G01","type":"mcq","marks":1,"part":"A","module":3,"topic":"Electrical","question":"The Electricity at Work Regulations 1989 require electrical systems to be:","options":["Tested by the HSE every year","Constructed and maintained so as to prevent danger, so far as reasonably practicable","Used only by people over 21","Fitted with 230 V sockets"],"answer":1,"citation":"EAWR 1989 reg 4","rationale":"Reg 4: all systems must be constructed, maintained and used so as to prevent danger, so far as is reasonably practicable. Work on live conductors is only allowed under the strict conditions of reg 14."},{"id":"N2-G02","type":"mcq","marks":1,"part":"A","module":3,"topic":"Electrical","question":"On a 110 V centre-tapped-to-earth (reduced low voltage) site supply, the maximum voltage between a live conductor and earth is:","options":["25 V","55 V","110 V","230 V"],"answer":1,"citation":"HSE HSG141; BS 7375","rationale":"The transformer winding is centre-tapped to earth, so each live conductor is only 55 V to earth. This greatly reduces the severity of an electric shock compared with 230 V."},{"id":"N2-Z01","type":"mcq","marks":1,"part":"A","module":3,"topic":"Temporary works","question":"Under BS 5975, who co-ordinates all temporary works activities on site?","options":["The temporary works co-ordinator (TWC)","The scaffolder","The client","The CDM principal designer"],"answer":0,"citation":"BS 5975:2019; CDM 2015 reg 19","rationale":"The TWC manages the temporary works procedure: register, design brief, design checks, and permits to load/strike. CDM reg 19 requires steps to prevent any structure collapsing during construction."},{"id":"N2-P01","type":"mcq","marks":1,"part":"A","module":3,"topic":"Lifting and work equipment","question":"A site crane that is NOT used to lift people must have a thorough examination at least every:","options":["3 months","6 months","12 months (or per a written examination scheme)","5 years"],"answer":2,"citation":"LOLER 1998 reg 9(3)","rationale":"Lifting equipment: at least every 12 months; equipment for lifting people and all lifting accessories: at least every 6 months; or in either case per a written examination scheme, and after exceptional circumstances."},{"id":"N2-P02","type":"mcq","marks":1,"part":"A","module":3,"topic":"Lifting and work equipment","question":"PUWER 1998 reg 4 requires that work equipment is:","options":["Painted yellow","Suitable for the purpose for which it is used or provided","Less than 5 years old","Only used on weekdays"],"answer":1,"citation":"PUWER 1998 reg 4","rationale":"Equipment must be suitable by design, construction or adaptation for the work and conditions where it is used. PUWER also requires maintenance (reg 5), inspection (reg 6), training (reg 9) and guarding (reg 11)."},{"id":"N2-X01","type":"mcq","marks":1,"part":"A","module":4,"topic":"Excavations","question":"In which CAT mode might a buried live cable carrying little or NO load NOT be detected?","options":["Power mode","Genny mode","Radio mode","None - a CAT always finds every cable"],"answer":0,"citation":"HSE HSG47 Avoiding danger from underground services","rationale":"Power mode only detects cables carrying a significant load. Use Radio mode and a signal generator (Genny) as well, use service drawings, and dig trial holes by hand. A CAT never proves an area is clear."},{"id":"N2-X02","type":"mcq","marks":1,"part":"A","module":4,"topic":"Excavations","question":"HSG47 advises that mechanical excavators should NOT be used within what distance of the indicated line of a buried service?","options":["0.5 m","1 m","2 m","5 m"],"answer":0,"citation":"HSE HSG47","rationale":"Within 0.5 m of the indicated line, use hand tools (spades and shovels with care) to expose the service. Locating devices are not precise, so the safe zone applies on both sides of the marked line."},{"id":"N2-Q01","type":"mcq","marks":1,"part":"A","module":4,"topic":"Confined spaces","question":"Which of these is a \'specified risk\' under the Confined Spaces Regulations 1997?","options":["Slipping on a wet floor","Loss of consciousness from gas, fume, vapour or lack of oxygen","Sunburn","Noise from a breaker"],"answer":1,"citation":"Confined Spaces Regs 1997 reg 1","rationale":"Specified risks: fire or explosion; loss of consciousness from raised body temperature; loss of consciousness or asphyxiation from gas, fume, vapour or lack of oxygen; drowning from a rising liquid level; asphyxiation or entrapment by a free-flowing solid."},{"id":"N2-Q02","type":"mcq","marks":1,"part":"A","module":4,"topic":"Confined spaces","question":"Under the Confined Spaces Regulations 1997, no one may enter a confined space unless:","options":["Suitable emergency rescue arrangements are in place","The space is less than 2 m deep","The person has a mobile phone","A dust mask is worn"],"answer":0,"citation":"Confined Spaces Regs 1997 reg 5","rationale":"Reg 5: suitable and sufficient arrangements for rescue must be in place before entry. Reg 4: avoid entry where reasonably practicable; otherwise use a safe system of work (often a permit to work)."},{"id":"N2-DM1","type":"mcq","marks":1,"part":"A","module":4,"topic":"Demolition","question":"Under CDM 2015, the arrangements for demolition or dismantling must be:","options":["Agreed verbally on the day","Recorded in writing before the demolition work begins","Approved by the local council","Sent to HSE on an F10"],"answer":1,"citation":"CDM 2015 reg 20","rationale":"Reg 20: demolition must be planned and carried out to prevent danger or reduce it to as low as reasonably practicable, and the arrangements must be recorded in writing before the work begins."},{"id":"N2-DM2","type":"mcq","marks":1,"part":"A","module":4,"topic":"Demolition","question":"Before demolishing a building built before 2000, which asbestos survey is needed?","options":["A management survey","A refurbishment and demolition survey","A visual walk-round only","No survey - asbestos was banned in 1985"],"answer":1,"citation":"CAR 2012 regs 5 and 7; HSE HSG264","rationale":"A refurbishment and demolition survey is intrusive and locates all asbestos, as far as reasonably practicable, so it can be removed before demolition. Asbestos use was banned in the UK in 1999."},{"id":"N2-Y01","type":"mcq","marks":1,"part":"A","module":4,"topic":"Environment","question":"Depositing controlled waste without an environmental permit (fly-tipping) is an offence under:","options":["Environmental Protection Act 1990 s.33","HSWA 1974 s.2","CDM 2015 reg 13","RIDDOR 2013"],"answer":0,"citation":"Environmental Protection Act 1990 s.33","rationale":"Section 33 prohibits unauthorised deposit, treatment or disposal of waste. Section 34 (duty of care) requires waste to go only to authorised persons with a written description (waste transfer note)."},{"id":"N2-Y02","type":"mcq","marks":1,"part":"A","module":4,"topic":"Environment","question":"How long must hazardous waste consignment notes be kept by the producer?","options":["6 months","1 year","2 years","3 years"],"answer":3,"citation":"Hazardous Waste (England and Wales) Regulations 2005","rationale":"Hazardous waste consignment notes: keep for 3 years. Non-hazardous waste transfer notes: keep for 2 years."},{"id":"N2-B01","type":"multi","marks":2,"part":"B","module":4,"topic":"Working at height","focusArea":"Working at height","question":"Which TWO of these MITIGATE the consequences of a fall (rather than avoid or prevent it)?","options":["Safety nets","Guard rails on a scaffold platform","Air bags / soft-landing systems","Doing the work from the ground with long-reach tools","A MEWP with a guarded platform"],"answers":[0,2],"citation":"WAHR 2005 reg 6(5)","rationale":"Hierarchy: avoid work at height (long-reach tools) -> prevent falls (guard rails, guarded MEWP platform) -> mitigate the distance and consequences of a fall (nets, air bags, fall arrest)."},{"id":"N2-B02","type":"multi","marks":2,"part":"B","module":2,"topic":"Manual handling","focusArea":"Manual handling","question":"Which TWO of these belong to the \'Load\' part of a TILE assessment?","options":["The load is heavy or bulky","The load is hot, sharp or unstable","Poor lighting in the work area","The task involves twisting","The worker is pregnant"],"answers":[0,1],"citation":"MHOR 1992 Sch 1; HSE L23","rationale":"TILE = Task (twisting, stooping, carrying distance), Individual (capability, health, pregnancy), Load (heavy, bulky, unstable, hot, sharp), Environment (space, floors, lighting, weather)."},{"id":"N2-B03","type":"multi","marks":2,"part":"B","module":2,"topic":"Vibration","focusArea":"Vibration","question":"Which TWO are the daily hand-arm vibration values under the Control of Vibration at Work Regulations 2005?","options":["Action value 2.5 m/s2 A(8)","Action value 0.5 m/s2 A(8)","Limit value 5.0 m/s2 A(8)","Limit value 1.15 m/s2 A(8)","Limit value 10 m/s2 A(8)"],"answers":[0,2],"citation":"CVWR 2005 reg 4","rationale":"Hand-arm: EAV 2.5 m/s2 (100 HSE points), ELV 5.0 m/s2 (400 points). The 0.5 and 1.15 m/s2 figures are the WHOLE-BODY vibration EAV and ELV."},{"id":"N2-B04","type":"multi","marks":2,"part":"B","module":2,"topic":"Asbestos","focusArea":"Asbestos","question":"An operative thinks they have just disturbed asbestos. Which TWO actions are correct?","options":["Stop work immediately","Sweep up the debris so no one trips","Keep people away and restrict access to the area","Carry on wearing a dust mask","Vacuum the dust with a normal site vacuum"],"answers":[0,2],"citation":"CAR 2012 reg 15; HSE asbestos emergency procedures","rationale":"Stop work, keep others out, don\'t try to clean up (no sweeping or ordinary vacuums), report to the supervisor, and have the material sampled. Contaminated clothing is decontaminated or bagged as asbestos waste."},{"id":"N2-B05","type":"multi","marks":2,"part":"B","module":2,"topic":"Dust","focusArea":"Dust","question":"Which TWO are effective ENGINEERING controls for silica dust when cutting blocks with a power saw?","options":["Water suppression","On-tool extraction (H or M class vacuum)","Dry sweeping afterwards","An FFP1 disposable mask","Opening the site cabin windows"],"answers":[0,1],"citation":"COSHH 2002 reg 7; HSE CIS54","rationale":"Control dust at source with water or on-tool extraction, then use suitable face-fit tested RPE (typically FFP3) as well. Dry sweeping spreads dust; FFP1 is inadequate for RCS."},{"id":"N2-B06","type":"multi","marks":2,"part":"B","module":2,"topic":"Noise","focusArea":"Noise","question":"Workers are exposed above 85 dB(A). Which TWO actions does the Control of Noise at Work Regulations 2005 require?","options":["Mark hearing protection zones and make hearing protection mandatory there","Provide health surveillance (hearing checks)","Give workers a pay rise","Turn up radios so workers can hear instructions","Do nothing until 87 dB(A)"],"answers":[0,1],"citation":"CNWR 2005 regs 6, 7 and 9","rationale":"At the upper EAV (85 dB(A)): a programme of noise-reduction measures, hearing protection zones with mandatory hearing protection, and health surveillance for those at risk. 87 dB(A) is the limit, which must never be exceeded."},{"id":"N2-B07","type":"multi","marks":2,"part":"B","module":3,"topic":"Vehicles/pedestrians","focusArea":"Vehicles/pedestrians","question":"Which TWO measures BEST separate pedestrians from vehicles on site?","options":["Separate pedestrian routes with physical barriers","Separate pedestrian and vehicle entrances/gates","Asking drivers to drive carefully","Hi-vis vests for visitors only","A sign saying \'Beware of vehicles\'"],"answers":[0,1],"citation":"CDM 2015 reg 27; HSE HSG144","rationale":"Segregation is the key control: separate routes and gates with physical barriers. Signs, hi-vis and instructions are lower-level controls that support segregation."},{"id":"N3-TW1","type":"mcq","marks":1,"part":"A","module":3,"topic":"Temporary works","question":"Which of these is an example of temporary works?","options":["Formwork and falsework for a concrete slab","The finished brick façade","The permanent roof trusses","Kitchen fittings"],"answer":0,"citation":"BS 5975:2019","rationale":"Temporary works support or protect the permanent works while they are built: formwork, falsework, props, excavation support, scaffolds, hoardings and crane bases."},{"id":"N3-TW2","type":"mcq","marks":1,"part":"A","module":3,"topic":"Temporary works","question":"Under BS 5975, what must be issued before formwork is loaded with concrete?","options":["A permit to load","An F10","A hot-work permit","A RIDDOR report"],"answer":0,"citation":"BS 5975:2019","rationale":"A permit to load confirms the temporary works have been checked as built to the design and are ready to take load. A permit to strike is needed before removal."},{"id":"N3-TW3","type":"mcq","marks":1,"part":"A","module":3,"topic":"Temporary works","question":"Under BS 5975:2019, who sets up the temporary works procedure in an organisation and appoints the TWC?","options":["The designated individual (DI)","The scaffolder","The client\'s architect","The HSE inspector"],"answer":0,"citation":"BS 5975:2019","rationale":"The designated individual is responsible for establishing the organisation\'s temporary works procedure and for appointing competent TWCs."},{"id":"N3-TW4","type":"mcq","marks":1,"part":"A","module":3,"topic":"Temporary works","question":"Which BS 5975 design check category requires the check to be done by an independent organisation?","options":["Category 0","Category 1","Category 2","Category 3"],"answer":3,"citation":"BS 5975:2019","rationale":"Categories 0-3 rise with complexity. Category 3 (complex or innovative designs) must be checked by an independent organisation."},{"id":"N3-TW5","type":"mcq","marks":1,"part":"A","module":3,"topic":"Temporary works","question":"Who normally helps the temporary works co-ordinator by supervising temporary works on site?","options":["The temporary works supervisor (TWS)","The client","The principal designer","The quantity surveyor"],"answer":0,"citation":"BS 5975:2019","rationale":"The TWS may be appointed to assist the TWC, supervising temporary works on site day to day. The TWC keeps overall responsibility."},{"id":"N3-TW6","type":"mcq","marks":1,"part":"A","module":3,"topic":"Temporary works","question":"A ganger wants to remove two props early to make room for deliveries. What should happen?","options":["Nothing may be removed without the TWC\'s permit to strike","Remove them if the concrete looks hard","Ask the crane driver","Remove one at a time"],"answer":0,"citation":"BS 5975:2019; CDM 2015 reg 19","rationale":"Unauthorised alteration or early removal of temporary works is a classic cause of collapse. Only the TWC can authorise striking, through a permit to strike."},{"id":"N3-SS1","type":"mcq","marks":1,"part":"A","module":3,"topic":"Site setup and signs","question":"A yellow triangular sign with a black symbol means:","options":["Prohibition","Mandatory action","Warning of a hazard","Safe condition"],"answer":2,"citation":"Health and Safety (Safety Signs and Signals) Regs 1996","rationale":"Yellow triangle = warning. Red circle with a bar = prohibition. Blue circle = mandatory. Green square/rectangle = safe condition (first aid, escape)."},{"id":"N3-SS2","type":"mcq","marks":1,"part":"A","module":3,"topic":"Site setup and signs","question":"A red circular sign with a diagonal bar means:","options":["You must do this","You must not do this","Fire equipment","First aid"],"answer":1,"citation":"Health and Safety (Safety Signs and Signals) Regs 1996","rationale":"Red circle with diagonal bar = prohibition (for example \'No smoking\'). Red squares mark fire-fighting equipment."},{"id":"N3-SS3","type":"mcq","marks":1,"part":"A","module":3,"topic":"Site setup and signs","question":"A green sign on site indicates:","options":["A hazard","A safe condition, such as first aid or an escape route","Mandatory PPE","Fire-fighting equipment"],"answer":1,"citation":"Health and Safety (Safety Signs and Signals) Regs 1996","rationale":"Green = safe condition: first aid, emergency exits, escape routes and assembly points."},{"id":"N3-SS4","type":"mcq","marks":1,"part":"A","module":3,"topic":"Site setup and signs","question":"Under CDM 2015 reg 18, the perimeter of a construction site must be:","options":["Identified by suitable signs and fenced off where necessary","Painted red","Guarded 24 hours a day","Lit all night"],"answer":0,"citation":"CDM 2015 reg 18","rationale":"Reg 18: keep the site in good order and, where necessary in the interests of health and safety, identify the perimeter with signs and fence it off."},{"id":"N3-SS5","type":"mcq","marks":1,"part":"A","module":3,"topic":"Site setup and signs","question":"Which document must an employer display (or make easily accessible electronically) for employees?","options":["The employers\' liability insurance certificate","The company\'s bank statements","The client\'s contract","The CITB levy return"],"answer":0,"citation":"Employers\' Liability (Compulsory Insurance) Regulations 1998","rationale":"Employers must hold employers\' liability insurance and display the certificate where employees can read it; electronic access is allowed."},{"id":"N3-SS6","type":"mcq","marks":1,"part":"A","module":3,"topic":"Site setup and signs","question":"When planning a site layout, which arrangement is BEST?","options":["Separate pedestrian and vehicle access points","One shared gate for everyone","Welfare in the middle of the plant area","Materials stored on pedestrian routes"],"answer":0,"citation":"CDM 2015 reg 27; HSE HSG144","rationale":"Plan the layout before work starts: separate vehicle and pedestrian access, safe routes to welfare, and storage and plant areas away from walkways."},{"id":"N3-LD1","type":"mcq","marks":1,"part":"A","module":1,"topic":"Leadership","question":"HSE\'s leaflet INDG417 \'Leading health and safety at work\' is built around which four actions?","options":["Plan, Deliver, Monitor, Review","Stop, Think, Act, Review","Identify, Assess, Control, Record","Eliminate, Reduce, Isolate, Control"],"answer":0,"citation":"HSE INDG417","rationale":"INDG417 sets out Plan, Deliver, Monitor and Review for directors and leaders."},{"id":"N3-LD2","type":"mcq","marks":1,"part":"A","module":1,"topic":"Leadership","question":"Under HSWA s37, a director can be personally prosecuted when an offence by the company is committed with their:","options":["Consent, connivance or neglect","Signature on the contract only","Absence on holiday","Knowledge of the site address"],"answer":0,"citation":"HSWA 1974 s.37","rationale":"Directors, managers and company officers are personally liable where the company\'s offence was committed with their consent or connivance, or was attributable to their neglect."},{"id":"N3-LD3","type":"mcq","marks":1,"part":"A","module":1,"topic":"Leadership","question":"Which is a LEADING indicator of safety performance?","options":["Number of site inspections carried out and near misses reported","Number of RIDDOR reports","Days lost to injury","Number of prosecutions"],"answer":0,"citation":"HSE HSG65","rationale":"Leading indicators measure activity that prevents harm (inspections, training, near-miss reporting). Lagging indicators count harm after it happens."},{"id":"N3-LD4","type":"mcq","marks":1,"part":"A","module":1,"topic":"Leadership","question":"You walk past an operative working without edge protection. The saying \'the standard you walk past...\' finishes:","options":["...is the standard you accept","...is someone else\'s problem","...is acceptable if they are quick","...is the client\'s risk"],"answer":0,"citation":"HSE leadership guidance","rationale":"Ignoring unsafe work tells everyone it is acceptable. Stop the work and put it right."},{"id":"N3-LD5","type":"mcq","marks":1,"part":"A","module":1,"topic":"Leadership","question":"Which approach to near-miss reporting builds the BEST safety culture?","options":["Thank people for reporting and act on what they report","Discipline anyone who reports a near miss","Only accept reports in writing from supervisors","Ignore near misses as nobody was hurt"],"answer":0,"citation":"HSE HSG65; HSG245","rationale":"A \'just\' reporting culture encourages reports; near misses are free lessons. Fear of blame stops reporting."},{"id":"N3-LD6","type":"mcq","marks":1,"part":"A","module":1,"topic":"Leadership","question":"Behavioural safety programmes mainly aim to:","options":["Encourage safe behaviour through observation, feedback and engagement","Replace physical controls with posters","Blame workers for accidents","Reduce the number of supervisors"],"answer":0,"citation":"HSE guidance on human factors (HSG48)","rationale":"Behavioural safety supports, but never replaces, good physical and management controls. It works through observation, positive feedback and involvement."},{"id":"N3-DM1","type":"mcq","marks":1,"part":"A","module":4,"topic":"Demolition","question":"What is the main British Standard code of practice for demolition?","options":["BS 6187","BS 5975","BS 7121","BS 7671"],"answer":0,"citation":"BS 6187:2011","rationale":"BS 6187 covers full and partial demolition. BS 5975 is temporary works, BS 7121 is cranes, BS 7671 is wiring regulations."},{"id":"N3-DM2","type":"mcq","marks":1,"part":"A","module":4,"topic":"Demolition","question":"What is generally the greatest hazard in demolition work?","options":["Premature or uncontrolled collapse of the structure","Sunburn","Paperwork errors","Noise complaints"],"answer":0,"citation":"CDM 2015 reg 20; BS 6187","rationale":"Reg 20 requires demolition to be planned to prevent danger, especially premature collapse. Use exclusion zones and controlled methods."},{"id":"N3-DM3","type":"mcq","marks":1,"part":"A","module":4,"topic":"Demolition","question":"Before demolition starts, existing services (gas, electricity, water) should be:","options":["Located and isolated or diverted","Left live for the demolition crew","Ignored if the building is empty","Turned off by the neighbours"],"answer":0,"citation":"BS 6187; HSE HSG47","rationale":"All services must be identified and disconnected, isolated or diverted, and confirmed in writing by the utility where needed."},{"id":"N3-DM4","type":"mcq","marks":1,"part":"A","module":4,"topic":"Demolition","question":"Which demolition method generally keeps operatives SAFEST?","options":["Remote high-reach machine with an exclusion zone","Operatives on the roof using hand tools","Pulling walls over by hand","Undermining walls at the base"],"answer":0,"citation":"BS 6187; HSE demolition guidance","rationale":"Methods that keep people off and away from the structure are preferred. Exclusion zones protect against falling debris."},{"id":"N3-DM5","type":"mcq","marks":1,"part":"A","module":4,"topic":"Demolition","question":"Asbestos found during the pre-demolition survey must normally be:","options":["Removed (by a licensed contractor where required) before demolition","Demolished along with the building","Covered with polythene","Wetted and left in place"],"answer":0,"citation":"CAR 2012 reg 7; HSG264","rationale":"As far as reasonably practicable, asbestos must be removed before major refurbishment or demolition, using licensed contractors where the work is licensable."},{"id":"N3-DM6","type":"mcq","marks":1,"part":"A","module":4,"topic":"Demolition","question":"Demolition debris falling onto a public footpath is BEST prevented by:","options":["Exclusion zones, debris netting/fans and closing or protecting the footpath","Asking the public to walk quickly","Working only at weekends","Hi-vis for pedestrians"],"answer":0,"citation":"HSWA 1974 s.3; HSE HSG151","rationale":"Protect the public with physical measures: exclusion zones, fans, netting, hoardings and footpath closures or covered walkways."},{"id":"N3-BS1","type":"mcq","marks":1,"part":"A","module":1,"topic":"Building Safety Act","question":"What is the \'golden thread\' under the Building Safety Act?","options":["Accurate, up-to-date information about a higher-risk building, kept throughout its life","A gold-coloured safety barrier","The fire brigade\'s hose","A training certificate"],"answer":0,"citation":"Building Safety Act 2022","rationale":"The golden thread is the information that allows people to understand the building and keep it safe, kept accurate and up to date throughout its life."},{"id":"N3-BS2","type":"mcq","marks":1,"part":"A","module":1,"topic":"Building Safety Act","question":"For a higher-risk building, what is needed before the building can be occupied?","options":["A completion certificate from the Building Safety Regulator (Gateway 3)","An F10","A RIDDOR report","Only the client\'s agreement"],"answer":0,"citation":"Building (Higher-Risk Buildings Procedures) (England) Regs 2023","rationale":"Gateway 3: the Building Safety Regulator must issue a completion certificate before occupation of a higher-risk building."},{"id":"N3-BS3","type":"mcq","marks":1,"part":"A","module":1,"topic":"Building Safety Act","question":"Under the Building Safety Act regime, certain serious safety occurrences on higher-risk building projects must be reported to:","options":["The Building Safety Regulator (mandatory occurrence reporting)","The local newspaper","The CITB","Nobody"],"answer":0,"citation":"Building Safety Act 2022; HRB Procedures Regs 2023","rationale":"Mandatory occurrence reporting requires principal designers and principal contractors to report safety occurrences (e.g. structural or fire safety risks) to the BSR."},{"id":"N3-BS4","type":"mcq","marks":1,"part":"A","module":1,"topic":"Building Safety Act","question":"The Building Safety Act extended the time limit for claims under the Defective Premises Act 1972 for past work to:","options":["30 years","6 years","10 years","50 years"],"answer":0,"citation":"Building Safety Act 2022 s.135","rationale":"Retrospectively, claims for past work can be brought within 30 years; for future work the limit is 15 years."},{"id":"N3-BS5","type":"mcq","marks":1,"part":"A","module":1,"topic":"Building Safety Act","question":"The Building Safety Act was introduced mainly in response to:","options":["The Grenfell Tower fire (2017)","The Ronan Point collapse","The 2008 financial crisis","Brexit"],"answer":0,"citation":"Building Safety Act 2022","rationale":"The Act followed the Grenfell Tower fire and Dame Judith Hackitt\'s review of building regulations and fire safety."},{"id":"N3-CS1","type":"mcq","marks":1,"part":"A","module":4,"topic":"Confined spaces","question":"Which of these is most likely to be a confined space?","options":["A sewer manhole chamber","An open car park","A site office with windows open","A scaffold platform"],"answer":0,"citation":"Confined Spaces Regs 1997; ACoP L101","rationale":"Confined spaces are substantially enclosed spaces with a specified risk: sewers, manholes, tanks, silos, chambers, pits and some trenches."},{"id":"N3-CS2","type":"mcq","marks":1,"part":"A","module":4,"topic":"Confined spaces","question":"How should the atmosphere in a confined space be checked?","options":["With a calibrated gas monitor before and during entry","By smelling the air","By lowering a lit match","Only once, the day before"],"answer":0,"citation":"Confined Spaces Regs 1997 reg 4; ACoP L101","rationale":"Test oxygen, flammable and toxic gases before entry and monitor continuously; conditions can change quickly."},{"id":"N3-CS3","type":"mcq","marks":1,"part":"A","module":4,"topic":"Confined spaces","question":"Why must a confined space never be ventilated with pure oxygen?","options":["It greatly increases the risk of fire and explosion","Oxygen is too expensive","It makes the air too cold","It is illegal to buy oxygen"],"answer":0,"citation":"Confined Spaces ACoP L101","rationale":"Oxygen enrichment makes materials, including clothing, burn fiercely. Use fresh air ventilation."},{"id":"N3-CS4","type":"mcq","marks":1,"part":"A","module":4,"topic":"Confined spaces","question":"A worker collapses inside a tank. What should the top person do?","options":["Raise the alarm and start the planned rescue - not enter without training and breathing apparatus","Climb in immediately to help","Leave the site","Ventilate with oxygen"],"answer":0,"citation":"Confined Spaces Regs 1997 reg 5","rationale":"Untrained would-be rescuers are often overcome too. Follow the pre-planned rescue arrangements required by reg 5."},{"id":"N3-WF1","type":"mcq","marks":1,"part":"A","module":2,"topic":"Welfare","question":"Under CDM 2015 Sch 2, drinking water on site must be:","options":["Wholesome, readily accessible and suitably marked where necessary","Bottled only","Provided only in summer","Kept in the site office"],"answer":0,"citation":"CDM 2015 Sch 2 para 3","rationale":"Provide an adequate supply of wholesome drinking water, readily accessible and marked where necessary, with cups unless supplied by a jet."},{"id":"N3-WF2","type":"mcq","marks":1,"part":"A","module":2,"topic":"Welfare","question":"Rest facilities on site must be suitable for:","options":["Pregnant women and nursing mothers to rest","Storing fuel","Parking vehicles","Storing materials"],"answer":0,"citation":"CDM 2015 Sch 2 para 5","rationale":"Rest facilities must include tables and seating, a means to boil water and heat food, and be suitable for pregnant women and nursing mothers to rest."},{"id":"N3-WF3","type":"mcq","marks":1,"part":"A","module":2,"topic":"Welfare","question":"Toilets on site must be:","options":["Suitable and sufficient, adequately ventilated and lit, and kept clean","Only provided for over 25 workers","Shared with the public","Emptied once a month"],"answer":0,"citation":"CDM 2015 Sch 2 para 1","rationale":"Toilets must be suitable and sufficient, ventilated, lit and clean. Separate rooms for men and women unless each toilet is in a lockable room for one person."},{"id":"N3-WF4","type":"mcq","marks":1,"part":"A","module":2,"topic":"Welfare","question":"Where workers must change into special work clothing, CDM 2015 requires:","options":["Changing rooms and facilities to store and dry clothing","Changing in the van","Nothing extra","A uniform allowance"],"answer":0,"citation":"CDM 2015 Sch 2 para 4","rationale":"Provide changing rooms (separate for men and women where needed) and lockable storage, with means to dry clothing."},{"id":"N3-FR1","type":"mcq","marks":1,"part":"A","module":3,"topic":"Fire","question":"What three things make up the fire triangle?","options":["Heat, fuel and oxygen","Heat, water and air","Fuel, smoke and light","Gas, spark and wood"],"answer":0,"citation":"HSE HSG168","rationale":"A fire needs heat, fuel and oxygen. Removing any one puts it out - the basis of fire prevention and extinguishing."},{"id":"N3-FR2","type":"mcq","marks":1,"part":"A","module":3,"topic":"Fire","question":"A fire extinguisher with a BLACK label contains:","options":["Carbon dioxide (CO2)","Water","Foam","Dry powder"],"answer":0,"citation":"BS EN 3","rationale":"Red = water, cream = foam, blue = dry powder, black = CO2, yellow = wet chemical. CO2 is suitable for electrical fires."},{"id":"N3-FR3","type":"mcq","marks":1,"part":"A","module":3,"topic":"Fire","question":"Oxy-fuel (oxy-acetylene/propane) cutting equipment must be fitted with:","options":["Flashback arrestors","A 30 mA RCD","A silencer","A spark plug"],"answer":0,"citation":"BCGA CP7; HSE guidance on gas welding","rationale":"Flashback arrestors stop a flame travelling back into the hoses and cylinders."},{"id":"N3-FR4","type":"mcq","marks":1,"part":"A","module":3,"topic":"Fire","question":"Which document gives guidance on fire safety on construction sites?","options":["HSE HSG168 Fire safety in construction","HSE HSG47","BS 5975","INDG163"],"answer":0,"citation":"HSE HSG168","rationale":"HSG168 covers fire risk assessment, hot work, emergency routes, alarms and fire-fighting on construction sites, with the Joint Code of Practice for larger projects."},{"id":"N3-EN1","type":"mcq","marks":1,"part":"A","module":1,"topic":"Enforcement","question":"Under HSWA s20, an HSE inspector may:","options":["Enter premises at any reasonable time and take samples, photographs and statements","Arrest workers","Fine a company on the spot","Close a road"],"answer":0,"citation":"HSWA 1974 s.20","rationale":"Inspectors can enter (with police if obstructed), examine, take measurements, photographs and samples, seize articles, and require information and signed statements."},{"id":"N3-EN2","type":"mcq","marks":1,"part":"A","module":1,"topic":"Enforcement","question":"Since 2008, the maximum prison sentence for most health and safety offences in the Crown Court is:","options":["2 years","6 months","5 years","Life"],"answer":0,"citation":"Health and Safety (Offences) Act 2008","rationale":"The 2008 Act made imprisonment (up to 2 years) available for most HSWA offences. Fines are unlimited."},{"id":"N3-EN3","type":"mcq","marks":1,"part":"A","module":1,"topic":"Enforcement","question":"Who enforces health and safety law on construction sites?","options":["The Health and Safety Executive (HSE)","The local council environmental health team","The CITB","The police only"],"answer":0,"citation":"Health and Safety (Enforcing Authority) Regs 1998","rationale":"HSE enforces on construction sites. Local authorities enforce in premises like offices, shops and warehouses."},{"id":"N3-GE1","type":"mcq","marks":1,"part":"A","module":3,"topic":"Electrical","question":"Plugs and sockets for 110 V site equipment are coloured:","options":["Yellow","Blue","Red","Green"],"answer":0,"citation":"BS EN 60309","rationale":"110 V = yellow, 230 V = blue, 400 V = red."},{"id":"N3-GE2","type":"mcq","marks":1,"part":"A","module":3,"topic":"Electrical","question":"230 V portable equipment on site should be protected by:","options":["A residual current device (RCD) rated at 30 mA","A larger fuse","Insulation tape","A 110 V plug"],"answer":0,"citation":"HSE HSG141; BS 7671","rationale":"A 30 mA RCD cuts the supply quickly if current leaks to earth, reducing the risk of a fatal shock. Battery or 110 V tools are preferred."},{"id":"N3-GE3","type":"mcq","marks":1,"part":"A","module":3,"topic":"Electrical","question":"Plant must work near overhead power lines. Following GS6, the FIRST step is to:","options":["Contact the line owner (DNO) to divert or isolate the line","Lower the boom and carry on","Use a banksman only","Work in the rain to earth the line"],"answer":0,"citation":"HSE GS6 Avoiding danger from overhead power lines","rationale":"First try to remove the risk: divert or switch off the line. If not possible, use barriers, goalposts and exclusion zones."},{"id":"N3-MH1","type":"mcq","marks":1,"part":"A","module":2,"topic":"Manual handling","question":"HSE\'s guideline weight for lifting close to the body at waist height is about:","options":["25 kg for men and 16 kg for women","50 kg for anyone","10 kg for men and 5 kg for women","There is no guidance"],"answer":0,"citation":"HSE L23 (MHOR 1992 guidance)","rationale":"These are filter values, not safe limits. Above them a more detailed assessment is needed."},{"id":"N3-MH2","type":"mcq","marks":1,"part":"A","module":2,"topic":"Manual handling","question":"Which is the FIRST step under the Manual Handling Operations Regulations 1992?","options":["Avoid hazardous manual handling so far as reasonably practicable","Issue back belts","Teach lifting technique","Assess the individual\'s fitness"],"answer":0,"citation":"MHOR 1992 reg 4","rationale":"Avoid -> assess what cannot be avoided -> reduce the risk. Training in technique is not a substitute for avoiding the handling."},{"id":"N3-MH3","type":"mcq","marks":1,"part":"A","module":2,"topic":"Manual handling","question":"Two operatives must team-lift a long beam. What is BEST practice?","options":["One person co-ordinates the lift and they agree signals beforehand","Each lifts when ready","The strongest lifts first","Lift and twist to save time"],"answer":0,"citation":"HSE L23","rationale":"Team lifts need a plan, clear communication and one person giving the commands. Team capacity is less than the sum of each person."},{"id":"N3-CO1","type":"mcq","marks":1,"part":"A","module":2,"topic":"COSHH and health","question":"Who must provide a safety data sheet for a hazardous product?","options":["The supplier","The site manager","HSE","The worker"],"answer":0,"citation":"UK REACH Article 31","rationale":"Suppliers provide safety data sheets. The employer still has to do a COSHH assessment of how the product is actually used."},{"id":"N3-CO2","type":"mcq","marks":1,"part":"A","module":2,"topic":"COSHH and health","question":"Wet cement can cause:","options":["Dermatitis and serious skin burns","Hearing loss","Vibration white finger","Sunburn only"],"answer":0,"citation":"HSE CIS26 Cement","rationale":"Wet cement is alkaline and can cause burns and irritant and allergic dermatitis. Use gloves, wash skin promptly and keep cement off clothing."},{"id":"N3-CO3","type":"mcq","marks":1,"part":"A","module":2,"topic":"COSHH and health","question":"How long must COSHH health surveillance records be kept?","options":["40 years","3 years","5 years","1 year"],"answer":0,"citation":"COSHH 2002 reg 11","rationale":"Health records must be kept for at least 40 years from the last entry, because occupational diseases can appear decades later."},{"id":"N3-CO4","type":"mcq","marks":1,"part":"A","module":2,"topic":"COSHH and health","question":"Leptospirosis (Weil\'s disease) is mainly caught from:","options":["Water or soil contaminated with rat urine","Breathing silica dust","Loud noise","Vibrating tools"],"answer":0,"citation":"HSE leptospirosis guidance; COSHH 2002","rationale":"Cover cuts, wear gloves, wash hands before eating, and control rats. Flu-like symptoms after work near water should be reported to a GP."},{"id":"N3-EX1","type":"mcq","marks":1,"part":"A","module":4,"topic":"Excavations","question":"Roughly how much does one cubic metre of soil weigh?","options":["More than a tonne","About 50 kg","About 200 kg","About 10 kg"],"answer":0,"citation":"HSE excavation guidance","rationale":"Even a small fall of soil can crush and suffocate someone, which is why even shallow trenches need support."},{"id":"N3-EX2","type":"mcq","marks":1,"part":"A","module":4,"topic":"Excavations","question":"Why should spoil heaps and vehicles be kept back from the edge of an excavation?","options":["Their weight can make the sides collapse and material can fall in","To make the site tidier","To shorten the digging time","So drivers can see the hole"],"answer":0,"citation":"CDM 2015 reg 22","rationale":"Surcharge loads near the edge increase the risk of collapse. Use stop blocks where vehicles tip into excavations."},{"id":"N3-LF1","type":"mcq","marks":1,"part":"A","module":3,"topic":"Lifting and work equipment","question":"Under LOLER reg 10, if a thorough examination finds a defect that is an existing or imminent risk of serious personal injury, the examiner must:","options":["Report it to the enforcing authority as well as the employer","Only tell the operator","Paint over it","Wait for the next examination"],"answer":0,"citation":"LOLER 1998 reg 10","rationale":"The equipment must not be used until put right, and a copy of the report goes to the enforcing authority."},{"id":"N3-LF2","type":"mcq","marks":1,"part":"A","module":3,"topic":"Lifting and work equipment","question":"Under BS 7121, who is responsible for planning a crane lift?","options":["The appointed person","The crane driver alone","The slinger","The client"],"answer":0,"citation":"BS 7121; LOLER 1998 reg 8","rationale":"The appointed person plans the lift and produces the lift plan; the crane supervisor controls it on site."},{"id":"N3-RA1","type":"mcq","marks":1,"part":"A","module":1,"topic":"RAMS and permits","question":"Under MHSWR 1999, the significant findings of a risk assessment must be recorded when the employer has:","options":["5 or more employees","1 or more employees","10 or more employees","50 or more employees"],"answer":0,"citation":"MHSWR 1999 reg 3(6)","rationale":"Employers with five or more employees must record the significant findings and any group identified as especially at risk."},{"id":"N3-RA2","type":"mcq","marks":1,"part":"A","module":1,"topic":"RAMS and permits","question":"A risk assessment must be reviewed when:","options":["There is reason to suspect it is no longer valid, or there has been a significant change","Only every 5 years","Only after an HSE visit","Never once signed"],"answer":0,"citation":"MHSWR 1999 reg 3(3)","rationale":"Review after changes to the work, equipment, people or site, after accidents or near misses, and periodically."},{"id":"N3-NO1","type":"mcq","marks":1,"part":"A","module":2,"topic":"Noise","question":"Noise-induced hearing loss is:","options":["Permanent and cannot be cured","Always temporary","Cured by hearing aids","Only caused by explosions"],"answer":0,"citation":"Control of Noise at Work Regs 2005; HSE L108","rationale":"Damage builds up over time and is irreversible. Tinnitus (ringing in the ears) is a common sign."},{"id":"N3-NO2","type":"mcq","marks":1,"part":"A","module":2,"topic":"Noise","question":"Under CNWR 2005 reg 6, the PRIORITY for controlling noise is:","options":["Reduce noise at source by technical and organisational means, before hearing protection","Issue ear defenders to everyone","Pay a noise allowance","Use louder radios"],"answer":0,"citation":"CNWR 2005 reg 6","rationale":"Eliminate or reduce noise at source (quieter methods, equipment, enclosures, distance, time limits). Hearing protection is for residual risk."},{"id":"N3-VI1","type":"mcq","marks":1,"part":"A","module":2,"topic":"Vibration","question":"Under CVWR 2005, health surveillance is required for workers likely to be exposed:","options":["Above the exposure action value, or otherwise at risk","Only above the limit value","Only if they ask","Never - it is optional"],"answer":0,"citation":"CVWR 2005 reg 7","rationale":"Health surveillance (e.g. HAVS questionnaires) is needed where workers are likely to be regularly exposed above the EAV or are otherwise at risk."},{"id":"N3-VI2","type":"mcq","marks":1,"part":"A","module":2,"topic":"Vibration","question":"Whole-body vibration is MOST associated with:","options":["Driving dumpers or plant over rough ground, causing back pain","Using a hammer drill","Typing","Using a hand saw"],"answer":0,"citation":"CVWR 2005; HSE L141","rationale":"Reduce WBV with good site haul roads, suitable seats and suspension, correct tyre pressures and limiting time on rough ground."},{"id":"N3-VP1","type":"mcq","marks":1,"part":"A","module":3,"topic":"Vehicles/pedestrians","question":"On site, a dumper driver must:","options":["Wear the seat belt where rollover protection (ROPS) is fitted","Carry passengers to save time","Drive with the skip raised","Leave the keys in when parked"],"answer":0,"citation":"PUWER 1998 reg 25; HSE HSG144","rationale":"Rollover protection only works if the driver is held in by the seat belt. Dumper overturns are a major cause of deaths."},{"id":"N3-VP2","type":"mcq","marks":1,"part":"A","module":3,"topic":"Vehicles/pedestrians","question":"A vehicle marshal (banksman) directing reversing should:","options":["Be trained, visible, standing in a safe position, and the only person giving signals","Stand directly behind the vehicle","Use whistles and shouting","Walk alongside the moving vehicle"],"answer":0,"citation":"HSE HSG144","rationale":"Only one trained marshal gives signals, from a safe position where the driver can see them. If the driver loses sight of them, the driver must stop."},{"id":"N3-QX1","type":"mcq","marks":1,"part":"A","module":1,"topic":"Exam and course","question":"In the SMSTS exam, when may the GE700 be used?","options":["Only in the last 15 minutes","Throughout the exam","Not at all","Only in the first 15 minutes"],"answer":0,"citation":"CITB SSP Scheme Rules Appendix G (Feb 2026)","rationale":"Answer what you know first; then use the last 15 minutes to look up the questions you flagged."},{"id":"N3-QX2","type":"mcq","marks":1,"part":"A","module":1,"topic":"Exam and course","question":"How many 2-mark questions are in the SMSTS exam?","options":["7","18","10","25"],"answer":0,"citation":"CITB SSP Scheme Rules Appendix G (Feb 2026)","rationale":"18 one-mark + 7 two-mark questions = 25 questions and 32 marks. The 2-mark questions cover the seven focus areas."},{"id":"N3-IN1","type":"mcq","marks":1,"part":"A","module":1,"topic":"Induction and training","question":"Under CDM 2015, who must ensure every worker receives a suitable site induction?","options":["The principal contractor","The client","The HSE","The worker\'s GP"],"answer":0,"citation":"CDM 2015 reg 13(4)","rationale":"The PC must ensure a suitable site induction is provided. Contractors must not let workers start until they have had one (reg 15)."},{"id":"N3-IN2","type":"mcq","marks":1,"part":"A","module":1,"topic":"Induction and training","question":"Under MHSWR 1999 reg 13, employees must be given health and safety training:","options":["When recruited and when exposed to new or increased risks","Only once in their career","Only if they ask","Only after an accident"],"answer":0,"citation":"MHSWR 1999 reg 13","rationale":"Training is needed on recruitment, with new equipment, technology or systems of work, and repeated periodically where appropriate - in working hours."},{"id":"N3-IN3","type":"mcq","marks":1,"part":"A","module":1,"topic":"Induction and training","question":"Which item is LEAST important in a site induction?","options":["The company\'s sales figures","Emergency procedures and assembly point","Site rules and main hazards","Welfare facilities and how to report concerns"],"answer":0,"citation":"CDM 2015 reg 13(4); HSE guidance","rationale":"Inductions cover site-specific hazards, rules, emergency arrangements, welfare, PPE and how to raise concerns."},{"id":"N3-IN4","type":"mcq","marks":1,"part":"A","module":1,"topic":"Induction and training","question":"Under CDM 2015, which duty holder must consult and engage with workers on health and safety?","options":["The principal contractor","The client","The building control officer","The insurer"],"answer":0,"citation":"CDM 2015 reg 14","rationale":"Reg 14: the PC must make and maintain arrangements to co-operate with workers and consult and engage them on matters affecting their health, safety and welfare."},{"id":"N3-IN5","type":"mcq","marks":1,"part":"A","module":1,"topic":"Induction and training","question":"Under MHSWR, a \'young person\' means anyone under:","options":["18","16","21","25"],"answer":0,"citation":"MHSWR 1999 regs 1 and 19","rationale":"Employers must assess risks to young people before they start, considering their inexperience and immaturity, and protect them (reg 19)."},{"id":"N3-IN6","type":"mcq","marks":1,"part":"A","module":1,"topic":"Induction and training","question":"Several workers have limited English. How should you make sure they understand the safety briefing?","options":["Use interpreters, translated material or pictures, and check understanding","Speak louder","Ask them to sign that they understood","Give them the briefing in writing only"],"answer":0,"citation":"MHSWR 1999 reg 10","rationale":"Information must be comprehensible. A signature is not proof of understanding - check it."},{"id":"N3-IN7","type":"mcq","marks":1,"part":"A","module":1,"topic":"Induction and training","question":"Under CDM 2015 reg 8, anyone appointed as a designer or contractor must have:","options":["The skills, knowledge and experience (and, if an organisation, the organisational capability) for the work","A university degree","More than 10 years in the industry","A CITB levy number"],"answer":0,"citation":"CDM 2015 reg 8","rationale":"Duty holders must be competent for the work and must not accept appointments they cannot fulfil safely."},{"id":"N3-IN8","type":"mcq","marks":1,"part":"A","module":1,"topic":"Induction and training","question":"A toolbox talk is BEST described as:","options":["A short, practical, task-specific briefing, with attendance recorded","A two-day classroom course","A written exam","A disciplinary meeting"],"answer":0,"citation":"MHSWR 1999 reg 10; good practice","rationale":"Toolbox talks refresh key messages on current tasks and risks. Keep them short, relevant and two-way."},{"id":"N3-MW1","type":"mcq","marks":1,"part":"A","module":2,"topic":"Mental health and wellbeing","question":"Under the Working Time Regulations 1998, workers are entitled to a rest break when the working day is longer than:","options":["6 hours (a 20-minute break)","4 hours (an hour\'s break)","8 hours (a 5-minute break)","There is no entitlement"],"answer":0,"citation":"Working Time Regulations 1998 reg 12","rationale":"Also: 11 consecutive hours\' rest in each 24 hours, and an average 48-hour week unless the worker opts out."},{"id":"N3-MW2","type":"mcq","marks":1,"part":"A","module":2,"topic":"Mental health and wellbeing","question":"The maximum AVERAGE working week under the Working Time Regulations (without an opt-out) is:","options":["48 hours","40 hours","60 hours","37.5 hours"],"answer":0,"citation":"Working Time Regulations 1998 reg 4","rationale":"Averaged normally over 17 weeks. Workers can opt out in writing; tiredness is still a hazard to manage."},{"id":"N3-MW3","type":"mcq","marks":1,"part":"A","module":2,"topic":"Mental health and wellbeing","question":"Does an employer have a legal duty to assess the risk of work-related stress?","options":["Yes - under MHSWR reg 3 it is a hazard like any other","No - it is a personal matter","Only for office staff","Only if the worker is off sick"],"answer":0,"citation":"MHSWR 1999 reg 3; HSE Management Standards","rationale":"HSE expects stress risks to be assessed, for example using the Management Standards (demands, control, support, relationships, role, change)."},{"id":"N3-MW4","type":"mcq","marks":1,"part":"A","module":2,"topic":"Mental health and wellbeing","question":"Under the Misuse of Drugs Act 1971 s8, it is an offence for the person in control of premises to:","options":["Knowingly permit the use or supply of controlled drugs there","Allow tea breaks","Sell soft drinks","Allow smoking outdoors"],"answer":0,"citation":"Misuse of Drugs Act 1971 s.8","rationale":"Have a clear drugs and alcohol policy, and act on suspected use, which also endangers others on site."},{"id":"N3-MW5","type":"mcq","marks":1,"part":"A","module":2,"topic":"Mental health and wellbeing","question":"A normally cheerful operative has become withdrawn and is often late. What is the BEST first step?","options":["Have a private, supportive conversation and signpost help","Give a written warning","Ignore it","Tell the rest of the gang"],"answer":0,"citation":"HSE Management Standards; HSE stress guidance","rationale":"Changes in behaviour can signal stress or poor mental health. Talk privately, listen, and point to support (occupational health, EAP, mental health first aiders, GP)."},{"id":"N3-MW6","type":"mcq","marks":1,"part":"A","module":2,"topic":"Mental health and wellbeing","question":"Which is a common sign that someone may be suffering from work-related stress?","options":["Changes in mood, increased absence and poorer concentration","Always arriving early","Better timekeeping","Taking on extra work happily"],"answer":0,"citation":"HSE stress guidance","rationale":"Watch for changes in behaviour, mood, attendance and performance - in individuals and across teams."},{"id":"N3-MW7","type":"mcq","marks":1,"part":"A","module":2,"topic":"Mental health and wellbeing","question":"Lone working on site is:","options":["Not banned in general, but must be risk-assessed - and some tasks (e.g. confined spaces, live electrical work) need others present","Always illegal","Always acceptable","Only allowed at night"],"answer":0,"citation":"MHSWR 1999 reg 3; HSE INDG73","rationale":"Assess the risk, set up contact arrangements and emergency procedures. Some high-risk work must never be done alone."},{"id":"N3-FA1","type":"mcq","marks":1,"part":"A","module":2,"topic":"First aid and emergencies","question":"Which regulations require employers to provide adequate first aid?","options":["Health and Safety (First-Aid) Regulations 1981","RIDDOR 2013","PUWER 1998","CDM 2015 Sch 2"],"answer":0,"citation":"Health and Safety (First-Aid) Regulations 1981","rationale":"Employers must assess needs and provide adequate and appropriate equipment, facilities and people."},{"id":"N3-FA2","type":"mcq","marks":1,"part":"A","module":2,"topic":"First aid and emergencies","question":"What is the role of an \'appointed person\' for first aid?","options":["Take charge of arrangements, look after the kit and call the emergency services","Treat serious injuries","Sign off RIDDOR reports","Carry out surgery"],"answer":0,"citation":"HSE L74","rationale":"An appointed person is not necessarily a trained first aider. In higher-hazard work, trained first aiders are normally also needed."},{"id":"N3-FA3","type":"mcq","marks":1,"part":"A","module":2,"topic":"First aid and emergencies","question":"A First Aid at Work (FAW) certificate is valid for:","options":["3 years","1 year","5 years","Life"],"answer":0,"citation":"HSE L74","rationale":"Requalify before expiry; HSE strongly recommends annual refresher training."},{"id":"N3-FA4","type":"mcq","marks":1,"part":"A","module":2,"topic":"First aid and emergencies","question":"Someone is in contact with a live cable. What must you do FIRST?","options":["Isolate the electrical supply without touching the person","Pull them away by the hand","Pour water on them","Start CPR immediately"],"answer":0,"citation":"HSE electric shock guidance","rationale":"Touching the casualty while they are live can electrocute you too. Isolate the supply or use non-conductive material only if it is safe."},{"id":"N3-FA5","type":"mcq","marks":1,"part":"A","module":2,"topic":"First aid and emergencies","question":"Which CDM 2015 regulations require emergency procedures and emergency routes and exits?","options":["Regs 30 and 31","Regs 4 and 5","Regs 12 and 13","Regs 22 and 24"],"answer":0,"citation":"CDM 2015 regs 30-31","rationale":"Plan arrangements for foreseeable emergencies, including evacuation, and keep escape routes clear, signed and lit."},{"id":"N3-FA6","type":"mcq","marks":1,"part":"A","module":2,"topic":"First aid and emergencies","question":"Following HSE guidance for higher-hazard work, a site with 120 workers should have at least how many FAW-trained first aiders?","options":["3 (one for every 50 or part of 50)","1","2","10"],"answer":0,"citation":"HSE L74 (guidance)","rationale":"Higher-hazard: more than 50 workers = at least one FAW first aider for every 50 employed (or part thereof). The needs assessment may show more are needed."},{"id":"N3-FA7","type":"mcq","marks":1,"part":"A","module":2,"topic":"First aid and emergencies","question":"Employers with 10 or more employees at the same premises must keep:","options":["An accident book","A visitors\' Facebook page","A list of employees\' home addresses on the noticeboard","A first aid certificate for every worker"],"answer":0,"citation":"Social Security (Claims and Payments) Regulations 1979","rationale":"The accident book (e.g. BI 510) records injuries; entries must be stored securely under data protection law."},{"id":"N3-FA8","type":"mcq","marks":1,"part":"A","module":2,"topic":"First aid and emergencies","question":"What should happen when the fire alarm sounds on site?","options":["Everyone goes to the assembly point and a roll call is taken","Workers finish their task first","Everyone gathers in the welfare cabin","Only the site manager leaves"],"answer":0,"citation":"CDM 2015 regs 30-32; HSE HSG168","rationale":"Use the signing-in register for the roll call so missing people can be reported to the fire service."},{"id":"N3-PP1","type":"mcq","marks":1,"part":"A","module":2,"topic":"PPE","question":"Which regulations require employers to provide suitable PPE?","options":["Personal Protective Equipment at Work Regulations 1992","RIDDOR 2013","LOLER 1998","Working Time Regulations 1998"],"answer":0,"citation":"PPE at Work Regulations 1992 reg 4","rationale":"PPE must be provided where risks cannot be adequately controlled by other means - it is the last resort."},{"id":"N3-PP2","type":"mcq","marks":1,"part":"A","module":2,"topic":"PPE","question":"Since 6 April 2022, the PPE Regulations also protect:","options":["\'Limb (b)\' workers (casual workers who are not employees)","Members of the public","Only apprentices","Only office staff"],"answer":0,"citation":"PPE at Work (Amendment) Regulations 2022","rationale":"Employers must now provide PPE, free of charge, to limb (b) workers as well as employees."},{"id":"N3-PP3","type":"mcq","marks":1,"part":"A","module":2,"topic":"PPE","question":"Under the PPE Regulations, employees must:","options":["Use PPE as trained and report any loss or defect","Buy their own PPE","Modify PPE to make it comfortable","Wear it only when the manager is watching"],"answer":0,"citation":"PPE at Work Regulations 1992 regs 10-11","rationale":"Employees must use PPE properly, return it to storage, and report loss or obvious defects."},{"id":"N3-PP4","type":"mcq","marks":1,"part":"A","module":2,"topic":"PPE","question":"An FFP3 disposable mask has an assigned protection factor (APF) of:","options":["20","4","10","40"],"answer":0,"citation":"HSE HSG53 Respiratory protective equipment at work","rationale":"FFP1 = APF 4, FFP2 = APF 10, FFP3 = APF 20. Only if it fits: tight-fitting RPE needs face-fit testing and a clean-shaven face."},{"id":"N3-PP5","type":"mcq","marks":1,"part":"A","module":2,"topic":"PPE","question":"Where several items of PPE are worn together (e.g. hard hat, ear defenders, RPE), they must be:","options":["Compatible, so each still works properly","From the same shop","The same colour","Replaced weekly"],"answer":0,"citation":"PPE at Work Regulations 1992 reg 5","rationale":"Badly matched PPE can break seals or reduce protection. Check compatibility and choose with the wearer."},{"id":"N3-PP6","type":"mcq","marks":1,"part":"A","module":2,"topic":"PPE","question":"Hearing protection and respiratory protective equipment are mainly covered by:","options":["Their own specific regulations (CNWR 2005 and COSHH 2002), not the PPE Regulations","Only the PPE Regulations","RIDDOR","No regulations"],"answer":0,"citation":"PPE at Work Regulations 1992 reg 3","rationale":"The PPE Regs do not apply where more specific regulations require PPE - e.g. noise, COSHH, asbestos, lead and ionising radiation."},{"id":"N3-PP7","type":"mcq","marks":1,"part":"A","module":2,"topic":"PPE","question":"A hard hat that has taken a heavy blow but looks undamaged should be:","options":["Replaced","Kept in use","Painted","Given to a visitor"],"answer":0,"citation":"BS EN 397; manufacturer\'s instructions","rationale":"Impact can cause hidden damage. Replace after a significant impact and at the end of its service life."},{"id":"N3-PP8","type":"mcq","marks":1,"part":"A","module":2,"topic":"PPE","question":"PPE is placed where in the hierarchy of control?","options":["Last - after elimination, substitution, engineering and administrative controls","First","Second","It replaces all other controls"],"answer":0,"citation":"MHSWR 1999 Sch 1; PPE Regs 1992","rationale":"PPE only protects the wearer and only if it fits, is worn and is maintained, so it is the last resort."},{"id":"N3-PU1","type":"mcq","marks":1,"part":"A","module":3,"topic":"Public protection","question":"Which section of HSWA requires employers to protect people who are NOT their employees?","options":["Section 3","Section 2","Section 7","Section 9"],"answer":0,"citation":"HSWA 1974 s.3","rationale":"Section 3 covers members of the public, visitors and other contractors affected by the work."},{"id":"N3-PU2","type":"mcq","marks":1,"part":"A","module":3,"topic":"Public protection","question":"Which HSE guidance covers protecting the public from construction work?","options":["HSG151 Protecting the public: your next move","HSG47","HSG65","INDG163"],"answer":0,"citation":"HSE HSG151","rationale":"HSG151 covers site boundaries, hoardings, out-of-hours security, children, traffic and work over public areas."},{"id":"N3-PU3","type":"mcq","marks":1,"part":"A","module":3,"topic":"Public protection","question":"Under the Occupiers\' Liability Act 1984, a site occupier owes a duty of care to:","options":["Trespassers, including children","Only invited visitors","Only employees","Nobody outside working hours"],"answer":0,"citation":"Occupiers\' Liability Act 1984","rationale":"Children are attracted to sites. Secure the perimeter and make the site safe out of hours."},{"id":"N3-PU4","type":"mcq","marks":1,"part":"A","module":3,"topic":"Public protection","question":"A skip placed on a public road needs:","options":["A skip permit from the highway authority","An F10","A hot-work permit","No permission"],"answer":0,"citation":"Highways Act 1980 s.139","rationale":"Skips on the highway need permission and must be lit and marked as the permit requires."},{"id":"N3-PU5","type":"mcq","marks":1,"part":"A","module":3,"topic":"Public protection","question":"A scaffold erected on or over a public footpath normally needs:","options":["A licence from the highway authority","Planning permission","A RIDDOR report","The police\'s agreement"],"answer":0,"citation":"Highways Act 1980 s.169","rationale":"Hoardings need a licence under s.172. Protect pedestrians with fans, covered walkways and lighting."},{"id":"N3-PU6","type":"mcq","marks":1,"part":"A","module":3,"topic":"Public protection","question":"At the end of the working day, which is the BEST practice for plant?","options":["Immobilise it, remove keys and lower buckets and attachments to the ground","Leave keys in for the morning","Park it next to the hoarding","Leave the boom raised"],"answer":0,"citation":"HSE HSG151","rationale":"Children and intruders may climb on or start plant. Also remove or board ladders and cover or fence excavations."},{"id":"N3-PU7","type":"mcq","marks":1,"part":"A","module":3,"topic":"Public protection","question":"To keep noisy work within agreed limits in advance, a contractor can apply to the local authority for:","options":["Prior consent under s61 of the Control of Pollution Act 1974","An F10","A section 60 notice","A Fee for Intervention"],"answer":0,"citation":"Control of Pollution Act 1974 s.61","rationale":"A s61 consent agrees methods and hours in advance. A s60 notice is served by the local authority to impose controls."},{"id":"N3-PU8","type":"mcq","marks":1,"part":"A","module":3,"topic":"Public protection","question":"The MOST effective way to stop children getting onto a site is:","options":["A secure perimeter hoarding or fence, kept in good repair and checked","Warning signs only","A guard dog","Hoping they stay away"],"answer":0,"citation":"HSE HSG151; CDM 2015 reg 18","rationale":"Physical barriers come first. Check them daily and after high winds, and secure the site out of hours."},{"id":"N3-AI1","type":"mcq","marks":1,"part":"A","module":1,"topic":"Accident investigation","question":"The main purpose of an accident investigation is to:","options":["Find the causes and prevent it happening again","Find someone to blame","Satisfy the insurer only","Avoid reporting to HSE"],"answer":0,"citation":"HSE HSG245 Investigating accidents and incidents","rationale":"Look for immediate, underlying and root causes; blame stops people being open."},{"id":"N3-AI2","type":"mcq","marks":1,"part":"A","module":1,"topic":"Accident investigation","question":"According to HSG245, root causes are usually:","options":["Failures in management systems, planning or supervision","The weather","Bad luck","The injured person\'s clothing"],"answer":0,"citation":"HSE HSG245","rationale":"Immediate causes (e.g. missing guard rail) lead back to underlying and root causes (e.g. no inspection regime, poor planning)."},{"id":"N3-AI3","type":"mcq","marks":1,"part":"A","module":1,"topic":"Accident investigation","question":"What is a \'near miss\'?","options":["An event that did not cause harm but had the potential to","An accident that caused a minor injury","A RIDDOR specified injury","A late delivery"],"answer":0,"citation":"HSE HSG245","rationale":"Near misses share causes with serious accidents. Report and investigate them."},{"id":"N3-AI4","type":"mcq","marks":1,"part":"A","module":1,"topic":"Accident investigation","question":"After making the area safe and caring for the injured, what should be done NEXT in an investigation?","options":["Preserve evidence and take witness statements as soon as possible","Clean up and restart work","Wait a month","Only fill in the accident book"],"answer":0,"citation":"HSE HSG245","rationale":"Photographs, measurements, equipment and early witness accounts give the most reliable picture."},{"id":"N3-AI5","type":"mcq","marks":1,"part":"A","module":1,"topic":"Accident investigation","question":"Which is an IMMEDIATE cause of a fall from a scaffold?","options":["A missing guard rail","No inspection regime","Poor company safety culture","Lack of planning"],"answer":0,"citation":"HSE HSG245","rationale":"The immediate cause is the unsafe act or condition at the scene; the others are underlying or root causes."},{"id":"N3-AI6","type":"mcq","marks":1,"part":"A","module":1,"topic":"Accident investigation","question":"Who should normally be involved in investigating an accident on site?","options":["Management and the workforce (e.g. supervisors and safety representatives)","Only the injured person","Only the insurer","Only HSE"],"answer":0,"citation":"HSE HSG245","rationale":"Involving the workforce gives better information and better solutions. Investigations should be led by someone with suitable seniority and competence."},{"id":"N3-AI7","type":"mcq","marks":1,"part":"A","module":1,"topic":"Accident investigation","question":"An investigation finds the method statement was not followed. The BEST action is to:","options":["Find out why, then fix the cause (e.g. unrealistic method, lack of briefing or resources)","Dismiss the gang immediately","Do nothing","Rewrite the paperwork only"],"answer":0,"citation":"HSE HSG245; HSG48 Reducing error and influencing behaviour","rationale":"People often depart from methods that don\'t work in practice. Fix the system, then brief and monitor."},{"id":"N3-AI8","type":"mcq","marks":1,"part":"A","module":1,"topic":"Accident investigation","question":"How long must RIDDOR records be kept?","options":["At least 3 years","1 year","6 months","40 years"],"answer":0,"citation":"RIDDOR 2013 reg 12","rationale":"Record reportable incidents and over-3-day injuries, and keep the records for at least 3 years."}]}')},70402,e=>{"use strict";var t=e.i(99879);let a=t.default.questions;t.default.meta,e.s(["R",0,a,"v",0,function(e){return[...new Set(e.map(e=>e.topic))].sort()}])}]);